    (1201, 'SUB-1201', 'SBM3', 'ES LA PROMOCIÓN DEL OFICIAL Y SUBOFICIAL EN SITUACIÓN DE ACTIVIDAD AL GRADO POLICIAL INMEDIATO SUPERIOR. NOS REFERIMOS A:', 'ASCENSO', 'ART. 4', '186717'),
