    (1252, 'SUB-1252', 'SBM3', 'DE ACUERDO CON EL DETALLE ESTABLECIDO EN EL ARTÍCULO 47, ¿A QUIÉN PRESENTA EL PRESIDENTE DE LA JUNTA SELECTORA EL CUADRO DE MÉRITO DE ASCENSOS PARA OFICIALES SUBALTERNOS?', 'AL COMANDANTE GENERAL DE LA PNP', 'ART. 47', '186782'),
    (1253, 'SUB-1253', 'SBM3', 'SEGÚN EL MECANISMO FORMAL DISPUESTO EN EL ARTÍCULO 47, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS DESCRIBE CORRECTAMENTE EL PROCEDIMIENTO PARA LOS ASCENSOS DE SUBOFICIALES?', 'EL PRESIDENTE DE LA JUNTA SELECTORA AL DIRECTOR DE RECURSOS HUMANOS DE LA PNP', 'ART. 47', '186783'),
    (1254, 'SUB-1254', 'SBM3', '¿CUÁL ES LA INSTANCIA RESPONSABLE DE PRESENTAR EL CUADRO DE MÉRITO DE ASCENSO AL MINISTRO DEL INTERIOR TRATÁNDOSE DE OFICIALES SUPERIORES, SEGÚN LO ESTIPULADO EN LA LEY 31873?', 'EL COMANDANTE GENERAL DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 47', '186784'),
    (1255, 'SUB-1255', 'SBM3', 'BAJO LA ESTRUCTURA ESTABLECIDA EN EL ARTÍCULO 47, ¿QUÉ AUTORIDAD ES RESPONSABLE DE PRESENTAR EL CUADRO DE MÉRITO DE ASCENSOS DIRECTAMENTE AL PRESIDENTE DE LA REPÚBLICA?', 'EL MINISTRO DEL INTERIOR PARA OFICIALES GENERALES', 'ART. 47', '186785'),
    (1256, 'SUB-1256', 'SBM3', 'SEGÚN EL ARTÍCULO 33 DE LA LEY 31873, ¿CUÁL DE LOS SIGUIENTES CRITERIOS NO ES REQUERIDO PARA QUE LA ASIGNACIÓN DEL PUNTAJE POR EXPERIENCIA PARA EL SERVICIO POLICIAL SEA ACUMULATIVA?', 'PRESTAR SERVICIOS POR AL MENOS TRES AÑOS EN EL MISMO GRADO', 'ART. 33', '186787'),
    (1257, 'SUB-1257', 'SBM3', 'DE CONFORMIDAD CON EL ARTÍCULO 33, ¿EN QUÉ CIRCUNSTANCIA LA ASIGNACIÓN DE PUNTAJE POR CONDECORACIONES POR SERVICIOS MERITORIOS ES VÁLIDA?', 'SOLO PARA POSTULAR AL GRADO INMEDIATO SUPERIOR', 'ART. 33', '186788'),
    (1258, 'SUB-1258', 'SBM3', 'RESPECTO A LA ASIGNACIÓN DE PUNTAJE POR FELICITACIONES, ¿CUÁL DE LOS SIGUIENTES LÍMITES MÁXIMOS ES APLICABLE POR GRADO, SEGÚN EL ARTÍCULO 33?', 'HASTA TRES FELICITACIONES POR ACCIÓN DE ARMAS Y TRES ADMINISTRATIVAS', 'ART. 33', '186789'),
    (1259, 'SUB-1259', 'SBM3', 'DE ACUERDO CON EL ARTÍCULO 33, ¿CUÁL ES UNO DE LOS CRITERIOS PARA DETERMINAR EL INCREMENTO DE PUNTAJE POR SERVICIOS EN ZONAS DE ALTURA, FRONTERA Y SELVA?', 'LA DISPONIBILIDAD DE VÍAS DE ACCESIBILIDAD A LA ZONA GEOGRÁFICA', 'ART. 33', '186790'),
    (1260, 'SUB-1260', 'SBM3', '¿CUÁL ES EL VALOR PORCENTUAL OTORGADO AL DESEMPEÑO PERSONAL PROFESIONAL O TÉCNICO COMO PARTE DEL SUBFACTOR EVALUADO, CONFORME AL ARTÍCULO 33 DE LA LEY 31873?', '35%', 'ART. 33', '186791'),
    (1261, 'SUB-1261', 'SBM3', 'RESPECTO DE LA NULIDAD DE LOS ACTOS ADMINISTRATIVOS, SEÑALE USTED EL CONCEPTO INCORRECTO:', 'RESPECTO DEL ACTO DECLARADO NULO, LOS SERVIDORES PÚBLICOS DEBERÁN OPONERSE A SU EJECUCIÓN, FUNDANDO Y MOTIVANDO SU NEGATIVA.', 'ART. 11', '181833'),
    (1262, 'SUB-1262', 'SBM3', 'LOS ACTOS ADMINISTRATIVOS QUE AL RESOLVER CASOS PARTICULARES INTERPRETEN DE MODO EXPRESO Y CON CARÁCTER GENERAL EL SENTIDO DE LA LEGISLACIÓN, CONSTITUIRÁN:', 'PRECEDENTES ADMINISTRATIVOS.', 'TITULO PRELIMINAR ART. VI', '181834'),
    (1263, 'SUB-1263', 'SBM3', 'ART. V. FUENTES DEL PROCEDIMIENTO ADMINISTRATIVO.- SON FUENTES DEL PROCEDIMIENTO ADMINISTRATIVO: (SEÑALE EL INCORRECTO):', 'LOS ACUERDOS DE MESAS DIRECTIVAS DE LOS TRABAJADORES EVENTUALES.', 'TITULO PRELIMINAR ART. V', '181835'),
    (1264, 'SUB-1264', 'SBM3', 'PRECISE USTED A QUIÉN O QUIÉNES ALCANZA LA RESPONSABILIDAD SOLIDARIA POR EL INCUMPLIMIENTO DE LOS PLAZOS. MARCA LA CORRECTA:', 'AL SUPERIOR JERÁRQUICO.', 'ART. 143', '181836'),
    (1265, 'SUB-1265', 'SBM3', 'SON SUJETOS DEL PROCEDIMIENTO: (SEÑALE LA CORRECTA)', 'LOS ADMINISTRADOS.', 'ART. 50', '181837'),
    (1266, 'SUB-1266', 'SBM3', 'LAS DECLARACIONES DE LAS ENTIDADES QUE, EN EL MARCO DE NORMAS DE DERECHO PÚBLICO, ESTÁN DESTINADAS A PRODUCIR EFECTOS JURÍDICOS SOBRE LOS INTERESES, OBLIGACIONES O DERECHOS DE LOS ADMINISTRADOS DENTRO DE UNA SITUACIÓN CONCRETA, SON:', 'ACTOS ADMINISTRATIVOS.', 'ART. 1', '181839'),
    (1267, 'SUB-1267', 'SBM3', 'ES UNA OBLIGACIÓN DIRECTA DEL ÓRGANO ADMINISTRATIVO QUE LA TENGA ATRIBUIDA COMO PROPIA, SALVO EL CAMBIO DE COMPETENCIA POR MOTIVOS DE DELEGACIÓN O EVOCACIÓN, SEGÚN LO PREVISTO EN ESTA LEY.', 'EL EJERCICIO DE LA COMPETENCIA.', 'ART. 65', '181840'),
    (1268, 'SUB-1268', 'SBM3', 'LOS RECURSOS ADMINISTRATIVOS SON:', 'REVISIÓN, APELACIÓN Y RECONSIDERACIÓN.', 'ART. 207', '181841'),
    (1269, 'SUB-1269', 'SBM3', 'ART.207. RECURSOS ADMINISTRATIVOS: EL TÉRMINO PARA LA INTERPOSICIÓN DE LOS RECURSOS ES DE:(SEÑALE EL CORRECTO).', '15 DÍAS PERENTORIOS.', 'ART. 207', '181842'),
    (1270, 'SUB-1270', 'SBM3', 'EN EL ARTÍCULO VI - TÍTULO PRELIMINAR DE LA LEY 27444 - PRECEDENTES ADMINISTRATIVOS:', 'LA SOLA MODIFICACIÓN DE LOS CRITERIOS NO FACULTA A LA REVISIÓN DE OFICIO, EN SEDE ADMINISTRATIVA DE LOS ACTOS FIRMES.', 'TITULO PRELIMINAR ART. VI', '181843'),
    (1271, 'SUB-1271', 'SBM3', 'PRECISE MEDIANTE QUE RECURSOS PROCEDE LA CONTRADICCIÓN EN LA VÍA ADMINISTRATIVA:', 'RECURSOS ADMINISTRATIVOS.', 'ART. 206', '181844'),
    (1272, 'SUB-1272', 'SBM3', 'TITULO I. CAPÍTULO I. DE LOS ACTOS ADMINISTRATIVOS.- ARTÍCULO 3 - REQUISITOS DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS.- SON REQUISITOS DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS: (SEÑALE EL INCORRECTO):', 'PROCEDIMIENTO SINGULAR.', 'ART. 3', '181845'),
    (1273, 'SUB-1273', 'SBM3', 'MODALIDADES DEL ACTO ADMINISTRATIVO: UNA MODALIDAD ACCESORIA ......:', 'NO PUEDE SER APLICADA CONTRA EL FIN PERSEGUIDO POR EL ACTO ADMINISTRATIVO.', 'ART. 2', '181846'),
    (1274, 'SUB-1274', 'SBM3', 'ART. 113 - REQUISITOS DE LOS ESCRITOS.- TODO ESCRITO QUE SE PRESENTE ANTE CUALQUIER ENTIDAD DEBE CONTENER ENTRE OTROS LO SIGUIENTE: (SEÑALE EL INCORRECTO).', 'LA RELACIÓN DE DOMICILIOS ANTERIORES DONDE HA RADICADO PARA UNA REFERENCIA.', 'ART. 113', '181847'),
    (1275, 'SUB-1275', 'SBM3', 'ART.142 - PLAZO MÁXIMO DEL PROCEDIMIENTO ADMINISTRATIVO. NO PUEDE EXCEDER DE (. ) DÍAS DE PLAZO QUE TRANSCURRE DESDE QUE ES INICIADO EL PROCEDIMIENTO ADMINISTRATIVO DE EVALUACIÓN PREVIA HASTA AQUEL EN QUE SEA DICTADA LA RESOLUCIÓN RESPECTIVA; SALVO QUE LA LEY ESTABLEZCA TRÁMITES CUYO CUMPLIMENTO REQUIERE UNA DURACIÓN MAYOR: (SEÑALE LA RESPUESTA CORRECTA).', 'TREINTA DÍAS.', 'ART. 142', '181848'),
    (1276, 'SUB-1276', 'SBM3', 'REQUISITOS DE LOS ESCRITOS QUE SE PRESENTAN ANTE CUALQUIER ENTIDAD (SEÑALE LA RESPUESTA INCORRECTA):', 'NOMBRES Y APELLIDOS COMPLETOS, DOMICILIO Y NÚMERO DE DOCUMENTO NACIONAL DE IDENTIDAD DEL TITULAR DE LA ENTIDAD.', 'ART. 113', '181849'),
    (1277, 'SUB-1277', 'SBM3', 'FORMA DE LOS ACTOS ADMINISTRATIVOS: (SEÑALE LA INCORRECTA)', 'DEBE SER EXPRESADO EN LETRA ARIAL 12.', 'ART. 4', '181850'),
    (1278, 'SUB-1278', 'SBM3', 'ART.133: INICIO DE CÓMPUTO: EL PLAZO EXPRESADO EN DÍAS ES CONTADO A PARTIR DEL (. ..............) DE AQUEL EN QUE SE PRACTIQUE LA NOTIFICACIÓN O LA PUBLICACIÓN DEL ACTO, SALVO QUE ÉSTE SEÑALE UNA FECHA POSTERIOR, O QUE SEA NECESARIO EFECTUAR PUBLICACIONES SUCESIVAS, EN CUYO CASO EL CÓMPUTO ES INICIADO A PARTIR DE LA ÚLTIMA.', 'DÍA HÁBIL SIGUIENTE.', 'ART. 133', '181851'),
    (1279, 'SUB-1279', 'SBM3', 'ART. 190.- PRECISE USTED EL MOMENTO EN QUE PUEDE REALIZARSE EL DESISTIMIENTO DE ALGÚN ACTO REALIZADO EN EL PROCEDIMIENTO ADMINISTRATIVO:', 'PUEDE REALIZARSE ANTES DE QUE HAYA PRODUCIDO EFECTOS.', 'ART. 190', '181852'),
    (1280, 'SUB-1280', 'SBM3', 'TRATÁNDOSE DEL PLAZO PARA EL CUMPLIMIENTO DE ACTOS PROCEDIMENTALES INTERNOS A CARGO DE LAS ENTIDADES, LA NORMA LEGAL PUEDE ESTABLECER QUE SU CÓMPUTO SEA EN DÍAS..... :', 'CALENDARIO.', 'ART. 139', '181853'),
    (1281, 'SUB-1281', 'SBM3', 'DE LOS CONCEPTOS CONTENIDOS EN EL TÍTULO PRELIMINAR DE LA LEY 27444 Y QUE SE DETALLAN A CONTINUACIÓN, SEÑALE USTED CUÁL ES EL INCORRECTO:', 'ES FINALIDAD DE LA LEY 27444 GARANTIZAR LOS DERECHOS E INTERESES DE LA ADMINISTRACIÓN.', 'TITULO PRELIMINAR ART. III', '181854'),
    (1282, 'SUB-1282', 'SBM3', 'EL SIGUIENTE ENUNCIADO : LOS SUJETOS DEL PROCEDIMIENTO ADMINISTRATIVO DEBEN HACER PREVALECER EL CUMPLIMIENTO DE LA FINALIDAD DEL ACTO PROCEDIMENTAL, SOBRE AQUELLOS FORMALISMOS CUYA REALIZACIÓN NO INCIDA EN SU VALIDEZ, NO DETERMINEN ASPECTOS IMPORTANTES EN LA DECISIÓN FINAL, NO DISMINUYAN LAS GARANTÍAS DEL PROCEDIMIENTO, NI CAUSEN INDEFENSIÓN A LOS ADMINISTRADOS. CORRESPONDE AL PRINCIPIO DE:', 'EFICACIA. Ley N° 27444 - Ley del Procedimiento Administrativo General', 'TITULO PRELIMINAR ART. IV', '181855'),
    (1283, 'SUB-1283', 'SBM3', 'DE LOS TÍTULOS PLANTEADOS A CONTINUACIÓN, UNO DE ELLOS NO CORRESPONDE A LOS REQUISITOS DE VALIDEZ DE LOS ACTOS ADMINISTRTAIVOS:', 'SIMPLICIDAD.', 'ART. 3', '181856'),
    (1284, 'SUB-1284', 'SBM3', 'ART.207 - RECURSOS ADMINISTRATIVOS.- UNO DE LOS RECURSOS ADMINISTRATIVOS ES EL DE: (SEÑALE EL CORRECTO).', 'RECONSIDERACIÓN.', 'ART. 207', '181857'),
    (1285, 'SUB-1285', 'SBM3', 'TODO ESCRITO QUE SE PRESENTE ANTE CUALQUIER ENTIDAD DEBE CONTENER LO SIGUIENTE: (SEÑALE LA RESPUESTA INCORRECTA).', 'NOMBRE Y DNI DEL AUXILIAR DE CONTABILIDAD DE LA EMPRESA A LA CUÁL SE LE DEMANDA.', 'ART. 113', '181858'),
    (1286, 'SUB-1286', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ PRACTICARSE A MÁS TARDAR DENTRO DEL PLAZO DE:', 'CINCO DÍAS.', 'ART. 24', '181859'),
    (1287, 'SUB-1287', 'SBM3', 'PRECISE USTED QUÉ RESPONSABILIDAD GENERA EL INCUMPLIMIENTO INJUSTIFICADO DE LOS PLAZOS PREVISTOS PARA LAS ACTUACIONES DE LAS ENTIDADES.', 'RESPONSABILIDAD DISCIPLINARIA PARA LA AUTORIDAD OBLIGADA.', 'ART. 143', '181860'),
    (1288, 'SUB-1288', 'SBM3', 'PRECISE USTED EN ATENCIÓN A QUE RAZONES, LA AUTORIDAD A CARGO DEL PROCEDIMIENTO, PUEDE REDUCIR PLAZOS O ANTICIPAR LOS TÉRMINOS:', 'OPORTUNIDAD O CONVENIENCIA.', 'ART. 141', '181861'),
    (1289, 'SUB-1289', 'SBM3', 'ART. IV - PRINCIPIOS DEL PROCEDIMIENTO ADMINISTRATIVO.- PRINCIPIO DE PRESUNCIÓN DE VERACIDAD.- EN LA TRAMITACIÓN DEL PROCEDIMIENTO ADMINISTRATIVO, SE PRESUME QUE LOS DOCUMENTOS Y DECLARACIONES FORMULADOS POR LOS ADMINISTRADOS EN LA FORMA PRESCRITA POR ESTA LEY, RESPONDEN:', 'A LA VERDAD DE LOS HECHOS QUE ELLOS AFIRMAN', 'TITULO PRELIMINAR ART. IV', '181862'),
    (1290, 'SUB-1290', 'SBM3', 'EN EL CASO DE NO ENCONTRAR AL ADMINISTRADO U OTRA PERSONA EN EL DOMICILIO SEÑALADO EN EL PROCEDIMIENTO, EL NOTIFICADOR DEBERÁ :', 'COLOCAR UN AVISO EN DICHO DOMICILIO INDICANDO LA NUEVA FECHA EN QUE SE HARÁ EFECTIVA LA SIGUIENTE NOTIFICACIÓN.', 'ART. 21', '181863'),
    (1291, 'SUB-1291', 'SBM3', 'EL SIGUIENTE ENUNCIADO: QUIENES PARTICIPAN EN EL PROCEDIMIENTO DEBEN AJUSTAR SU ACTUACIÓN DE TAL MODO QUE SE DOTE AL TRÁMITE DE LA MÁXIMA DINÁMICA POSIBLE, EVITANDO ACTUACIONES PROCESALES QUE DIFICULTEN SU DESENVOLVIMIENTO O CONSTITUYAN MEROS FORMALISMOS, A FIN DE ALCANZAR UNA DECISIÓN EN TIEMPO RAZONABLE, SIN QUE ELLO RELEVE A LAS AUTORIDADES DEL RESPETO AL DEBIDO PROCEDIMIENTO O VULNERE EL ORDENAMIENTO...CORRESPONDE AL PRINCIPIO DE:', 'CELERIDAD.', 'TITULO PRELIMINAR ART. IV', '181864'),
    (1292, 'SUB-1292', 'SBM3', 'RECIBIDA LA SOLICITUD O LA DISPOSICIÓN DE AUTORIDAD SUPERIOR, SEGÚN EL CASO, PARA INICIAR UN PROCEDIMIENTO, LAS AUTORIDADES DE OFICIO DEBEN ASEGURARSE DE SU PROPIA COMPETENCIA PARA PROSEGUIR CON EL NORMAL DESARROLLO DEL PROCEDIMIENTO, SIGUIENDO LOS CRITERIOS APLICABLES AL CASO DE LA MATERIA : (SEÑALE LA CORRECTA)', 'EL TERRITORIO, EL TIEMPO, EL GRADO O LA CUANTÍA.', 'ART. 80', '181865'),
    (1293, 'SUB-1293', 'SBM3', 'LUEGO DE RESUELTO EL CONFLICTO DE COMPETENCIA, EL ÓRGANO QUE RESULTE COMPETENTE PARA CONOCER EL ASUNTO CONTINUA EL PROCEDIMIENTO SEGÚN SU ESTADO Y CONSERVA TODO LO ACTUADO, SALVO AQUELLO:', 'QUE NO SEA JURÍDICAMENTE POSIBLE.', 'ART. 87', '181866'),
    (1294, 'SUB-1294', 'SBM3', 'INDIQUE USTED DE LOS SIGUIENTES ENUNCIADOS, CUÁL CORRESPONDE AL PRINCIPIO DE IMPARCIALIDAD', 'LAS AUTORIDADES ADMINISTRATIVAS ACTÚAN SIN NINGUNA CLASE DE DISCRIMINACIÓN ENTRE LOS ADMINISTRADOS, OTORGÁNDOLES TRATAMIENTO Y TUTELA IGUALITARIOS FRENTE AL PROCEDIMIENTO, RESOLVIENDO CONFORME AL ORDENAMIENTO JURÍDICO Y CON ATENCIÓN AL INTERÉS GENERAL', 'TITULO PRELIMINAR ART. IV', '181867'),
    (1295, 'SUB-1295', 'SBM3', 'EL PRINCIPIO DE IMPULSO DE OFICIO CONSIDERA QUE:', 'LAS AUTORIDADES DEBEN DIRIGIR E IMPULSAR DE OFICIO EL PROCEDIMIENTO Y ORDENAR LA REALIZACIÓN O PRÁCTICA DE LOS ACTOS QUE RESULTEN CONVENIENTES PARA EL ESCLARECIMIENTO Y RESOLUCIÓN DE LAS CUESTIONES NECESARIAS', 'TITULO PRELIMINAR ART. IV', '181868'),
    (1296, 'SUB-1296', 'SBM3', 'ART. 191.- PRECISE USTED CUÁL ES LA FORMA EN QUE LA AUTORIDAD ADMINISTRATIVA PODRÁ DECLARAR EL ABANDONO DEL PROCEDIMIENTO INICIADO A SOLICITUD DEL ADMINISTRADO:', 'DE OFICIO O A SOLICITUD DEL ADMINISTRADO..', 'ART. 191', '181869'),
    (1297, 'SUB-1297', 'SBM3', 'INTEGRA UN SISTEMA ORGÁNICO QUE TIENE AUTONOMÍA RESPECTO DE OTRAS RAMAS DEL DERECHO:', 'EL ORDENAMIENTO JURÍDICO ADMINISTRATIVO.', 'TITULO PRELIMINAR ART. V', '181870'),
    (1298, 'SUB-1298', 'SBM3', 'ART. 12 - EFECTOS DE LA DECLARACIÓN DE NULIDAD.- LA DECLARACIÓN DE NULIDAD TENDRÁ EFECTO DECLARATIVO Y RETROACTIVO A LA FECHA DEL ACTO, SALVO :', 'DERECHOS ADQUIRIDOS DE BUENA FE POR TERCEROS, EN CUYO CASO OPERARÁ A FUTURO.', 'ART. 12', '181871'),
    (1299, 'SUB-1299', 'SBM3', 'SON FUENTES DEL PROCEDIMIENTO ADMINISTRATIVO, SEÑALE EL CORRECTO:', 'LAS DISPOSICIONES CONSTITUCIONALES.', 'TITULO PRELIMINAR ART. V', '181872'),
    (1300, 'SUB-1300', 'SBM3', 'EL SIGUIENTE ENUNCIADO : LAS NORMAS DE PROCEDIMIENTO DEBEN SER INTERPRETADAS EN FORMA FAVORABLE A LA ADMISIÓN Y DECISIÓN FINAL DE LAS PRETENSIONES DE LOS ADMINISTRADOS, DE MODO QUE SUS DERECHOS E INTERESES NO SEAN AFECTADOS POR LA EXIGENCIA DE ASPECTOS FORMALES QUE PUEDAN SER SUBSANADOS DENTRO DEL PROCEDIMIENTO, SIEMPRE QUE DICHA EXCUSA NO AFECTE DERECHOS DE TERCEROS O EL INTERÉS PÚBLICO. CORRESPONDE AL PRINCIPIO DE:', 'INFORMALISMO.', 'TITULO PRELIMINAR ART. IV', '181873')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

