    ('SUB-1294', 'A', 'LAS NORMAS DE PROCEDIMIENTO DEBEN SER INTERPRETADAS EN FORMA FAVORABLE A LA ADMISIÓN Y DECISIÓN FINAL DE LAS PRETENSIONES DE LOS ADMINISTRADOS, DE MODO QUE SUS DERECHOS E INTERESES NO SEAN AFECTADOS.', FALSE, 1),
    ('SUB-1294', 'B', 'EN LA TRAMITACIÓN DEL PROCEDIMIENTO ADMINISTRATIVO, SE PRESUME QUE LOS DOCUMENTOS Y DECLARACIONES FORMULADOS POR LOS ADMINISTRADOS EN LA FORMA PRESCRITA POR ESTA LEY, RESPONDEN A LA VERDAD DE LOS HECHOS.', FALSE, 2),
    ('SUB-1294', 'C', 'LAS AUTORIDADES ADMINISTRATIVAS ACTÚAN SIN NINGUNA CLASE DE DISCRIMINACIÓN ENTRE LOS ADMINISTRADOS, OTORGÁNDOLES TRATAMIENTO Y TUTELA IGUALITARIOS FRENTE AL PROCEDIMIENTO, RESOLVIENDO CONFORME AL ORDENAMIENTO JURÍDICO Y CON ATENCIÓN AL INTERÉS GENERAL', TRUE, 3),
    ('SUB-1294', 'D', 'LAS AUTORIDADES ADMINISTRATIVAS DEBEN ACTUAR CON RESPETO A LA CONSTITUCIÓN, LA LEY Y AL DERECHO, DENTRO DE LAS FACULTADES QUE LE ESTÉN ATRIBUIDAS Y DE ACUERDO CON LOS FINES PARA LOS QUE LES FUERON CONFERIDAS.', FALSE, 4),
    ('SUB-1294', 'E', 'QUIENES PARTICIPAN EN EL PROCEDIMIENTO DEBEN AJUSTAR SU ACTUACIÓN DE TAL MODO QUE SE DOTE AL TRÁMITE DE LA MÁXIMA DINÁMICA POSIBLE, EVITANDO ACTUACIONES PROCESALES QUE DIFICULTEN SU DESENVOLVIMIENTO O CONSTITUYAN MEROS FORMALISMOS, A FIN DE ALCANZAR UNA DECISIÓN EN TIEMPO RAZONABLE, SIN QUE ELLO RELEVE A LAS AUTORIDADES DEL RESPETO AL DEBIDO PROCEDIMIENTO O VULNERE EL ORDENAMIENTO.', FALSE, 5),
    ('SUB-1295', 'A', 'LAS AUTORIDADES DEBEN DIRIGIR E IMPULSAR DE OFICIO EL PROCEDIMIENTO Y ORDENAR LA REALIZACIÓN O PRÁCTICA DE LOS ACTOS QUE RESULTEN CONVENIENTES PARA EL ESCLARECIMIENTO Y RESOLUCIÓN DE LAS CUESTIONES NECESARIAS', TRUE, 1),
    ('SUB-1295', 'B', 'LA TRAMITACIÓN DE LOS PROCEDIMIENTOS ADMINISTRATIVOS SE SUSTENTARÁ EN LA APLICACIÓN DE LA FISCALIZACIÓN POSTERIOR.', FALSE, 2),
    ('SUB-1295', 'C', 'LA AUTORIDAD ADMINISTRATIVA DEBERÁ BRINDAR A LOS ADMINISTRADOS O SUS REPRESENTANTES INFORMACIÓN VERAZ, COMPLETA Y CONFIABLE SOBRE CADA TRÁMITE, DE MODO TAL QUE A SU INICIO, EL ADMINISTRADO PUEDA TENER UNA CONCIENCIA BASTANTE CERTERA DE CUÁL SERÁ EL RESULTADO FINAL QUE SE OBTENDRÁ.', FALSE, 3),
    ('SUB-1295', 'D', 'LA AUTORIDAD ADMINISTRATIVA DEBERÁ ESTABLECER REQUISITOS SIMILARES PARA TRÁMITES SIMILARES, GARANTIZANDO QUE LAS EXCEPCIONES A LOS PRINCIPIOS GENERALES NO SERÁN CONVERTIDOS EN LA REGLA GENERAL.', FALSE, 4),
