INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1301 a 1400
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1301, 'SUB-1301', 'SBM3', 'ART. 211 - REQUISITOS DEL RECURSO.- EL ESCRITO DEL RECURSO A PARTE DE SER AUTORIZADO POR LETRADO, DEBE CUMPLIR CON LOS REQUISITOS PREVISTOS EN EL ARTÍCULO 113 : (SEÑALE EL REQUISITO INCORRECTO).', 'NOMBRES Y APELLIDOS COMPLETOS DE SU CÓNYUGE, PADRES E HIJOS COMO FILIACIÓN.', 'ART. 113', '181874'),
    (1302, 'SUB-1302', 'SBM3', 'SON ACTOS ADMINISTRATIVOS: (SEÑALE LA RESPUESTA CORRECTA) .', 'LAS DECLARACIONES DE LAS ENTIDADES QUE, EN EL MARCO DE LAS NORMAS DE DERECHO PÚBLICO ESTÉN DESTINADAS A PRODUCIR EFECTOS JURÍDICOS SOBRE LOS INTERESES, OBLIGACIONES O DERECHOS DE LOS ADMINISTRADOS DENTRO DE UNA SITUACIÓN CONCRETA. Ley N° 27444 - Ley del Procedimiento Administrativo General', 'ART. 1', '181875'),
    (1303, 'SUB-1303', 'SBM3', 'LA COPIA DE CUALQUIER DOCUMENTO PÚBLICO, SIEMPRE QUE EXISTA CONSTANCIA DE QUE ES AUTÉNTICA, SEÑALE LA RESPUESTA CORRECTA:', 'GOZA DE LA MISMA VALIDEZ Y EFICACIA QUE ÉSTOS.', 'ART. 43', '181876'),
    (1304, 'SUB-1304', 'SBM3', 'CUÁNDO EL ERROR EN LA CALIFICACIÓN DEL RECURSO POR PARTE DEL RECURRENTE NO SERÁ OBSTÁCULO PARA SU TRAMITACIÓN? : MARCA LA CORRECTA', 'SI DEL ESCRITO SE DEDUZCA SU VERDADERO CARÁCTER.', 'ART. 213', '181877'),
    (1305, 'SUB-1305', 'SBM3', 'SE DECLARA ABANDONO DEL PROCEDIMIENTO, CUANDO EL ADMINISTRADO INCUMPLA ALGÚN TRÁMITE QUE SE HUBIERA SIDO REQUERIDO QUE PRODUZCA PARALIZACIÓN POR : MARCA EL CORRECTO:', '30 DÍAS.', 'ART. 191', '181878'),
    (1306, 'SUB-1306', 'SBM3', 'LA INTERPOSICIÓN DE CUALQUIER RECURSO, EXCEPTO LOS CASOS EN QUE UNA NORMA LEGAL ESTABLEZCA LO CONTRARIO, NO SUSPENDERÁ LA EJECUCIÓN DEL ACTO IMPUGNADO; NO OBSTANTE LO DISPUESTO EN EL NUMERAL ANTERIOR, LA AUTORIDAD A QUIEN COMPETA RESOLVER EL RECURSO SUSPENDE DE OFICIO O A PETICIÓN DE PARTE LA EJECUCIÓN DEL ACTO RECURRIDO CUANDO CONCURRA ALGUNA DE LAS SIGUIENTES CIRCUNSTANCIAS:', 'QUE SE APRECIE OBJETIVAMENTE LA EXISTENCIA DE UN VICIO DE NULIDAD TRASCENDENTE.', 'ART. 216', '181879'),
    (1307, 'SUB-1307', 'SBM3', 'EL PLAZO MÁXIMO PARA ACTOS DE MERO TRÁMITE Y DECIDIR PETICIONES DE ESE CARÁCTER ES :', '03 DÍAS.', 'ART. 132', '181880'),
    (1308, 'SUB-1308', 'SBM3', 'EL RÉGIMEN DE LA NOTIFICACIÓN CONSISTE EN : MARCA LA INCORRECTA', 'SI NO SE ENCUENTRA LA PERSONA, SE ENTREGA AL VECINO.', 'ART. 21', '181881'),
    (1309, 'SUB-1309', 'SBM3', 'LA LEY 27444 SEÑALA QUE, LOS ACTOS ADMINISTRATIVOS QUE AGOTEN LA VIA ADMINISTRATIVA PODRÁN SER:', 'IMPUGNADOS ANTE EL PODER JUDICIAL.', 'ART. 218', '181882'),
    (1310, 'SUB-1310', 'SBM3', 'ART. 50 - SUJETOS DEL PROCEDIMIENTO.- LA AUTORIDAD ADMINISTRATIVA ES EL AGENTE DE LAS ENTIDADES QUE, BAJO CUALQUIER RÉGIMEN JURÍDICO Y EJERCIENDO POTESTADES PÚBLICAS CONDUCEN: ( COMPLETE LO CORRECTO)', 'EL INICIO, LA INSTRUCCIÓN, LA SUSTANCIACIÓN, LA RESOLUCIÓN, LA EJECUCIÓN, O QUE DE OTRO MODO PARTICIPAN EN LA GESTIÓN DE LOS PROCEDIMIENTOS ADMINISTRATIVOS.', 'ART. 50', '181883'),
    (1311, 'SUB-1311', 'SBM3', 'MARQUE LA INCORRECTA: EL CITATORIO SE RIGE POR EL RÉGIMEN COMÚN DE LA NOTIFICACIÓN, HACIENDO CONSTAR EN ELLA LO SIGUIENTE:', 'EL DESAGRAVIO, EN CASO DE INASISTENCIA AL REQUERIMIENTO.', 'ART. 59', '181884'),
    (1312, 'SUB-1312', 'SBM3', 'LAS AUTORIDADES ADMINISTRATIVAS NO PODRÁN DEJAR DE RESOLVER LAS CUESTIONES QUE SE LES PROPONGA, POR DEFICIENCIA DE SUS FUENTES; EN TALES CASOS, ACUDIRÁN A:', 'LOS PRINCIPIOS DEL DERECHO ADMINISTRATIVO.', 'TITULO PRELIMINAR ART. VIII', '181885'),
    (1313, 'SUB-1313', 'SBM3', 'INDIQUE CUÁL ES EL ENUNCIADO CORRECTO QUE CORRESPONDE A LA COPIA DE LOS ESCRITOS:', 'EL CARGO ASÍ EXPEDIDO TIENE EL MISMO VALOR LEGAL QUE EL ORIGINAL.', 'ART. 114', '181886'),
    (1314, 'SUB-1314', 'SBM3', 'SE ENTIENDE POR PROCEDIMIENTO ADMINISTRATIVO AL (. ......................... ) TRAMITADOS EN LAS ENTIDADES, CONDUCENTES A LA EMISIÓN DE UN ACTO ADMINISTRATIVO QUE CONDUZCA EFECTOS JURÍDICOS INDIVIDUALES O INDIVIDUALIZABLES SOBRE INTERESES, OBLIGACIONES O DERECHOS DE LOS ADMINISTRADOS. (SEÑALE LA FRASE CORRECTA)', 'CONJUNTO DE ACTOS Y DILIGENCIAS.', 'ART. 29', '181887'),
    (1315, 'SUB-1315', 'SBM3', 'ART. 13 - ALCANCES DE LA NULIDAD.- LA NULIDAD PARCIAL DEL ACTO ADMINISTRATIVO NO ALCANZA A LAS OTRAS PARTES DEL ACTO QUE RESULTEN (..............................) DE LA PARTE NULA, SALVO QUE SEA SU CONSECUENCIA, NI IMPIDE LA PRODUCCIÓN DE EFECTOS PARA LOS CUALES NO OBSTANTE, EL ACTO PUEDA SER IDÓNEO, SALVO DISPOSICIÓN LEGAL EN CONTRARIO. ( SEÑALE LO CORRECTO)', 'INDEPENDIENTES.', 'ART. 13', '181888'),
    (1316, 'SUB-1316', 'SBM3', 'ART. 52 - CAPACIDAD PROCESAL.- TIENEN CAPACIDAD PROCESAL ANTE LAS ENTIDADES LAS PERSONAS QUE GOZAN DE ( ........................ ) CONFORME A LAS LEYES. (COMPLETE LO CORRECTO)', 'CAPACIDAD JURÍDICA.', 'ART. 52', '181889'),
    (1317, 'SUB-1317', 'SBM3', 'ART. 132.- A FALTA DE PLAZO ESTABLECIDO POR LEY EXPRESA, LAS ACTUACIONES DEBEN PRODUCIRSE DENTRO DE LO SIGUIENTE: (MARQUE EL ENUNCIADO CORRECTO).', 'PARA ACTOS DE MERO TRÁMITE Y DECIDIR PETICIONES DE ESE CARÁCTER: EN TRES DÍAS.', 'ART. 132', '181890'),
    (1318, 'SUB-1318', 'SBM3', 'COMPARECENCIA PERSONAL.- LAS ENTIDADES PUEDEN CONVOCAR LA COMPARECENCIA PERSONAL A SU SEDE, DE LOS ADMINISTRADOS SÓLO................(SEÑALE LA RESPUESTA CORRECTA).', 'CUANDO ASÍ LE HAYA SIDO FACULTADO EXPRESAMENTE POR LEY.', 'ART. 58', '181891'),
    (1319, 'SUB-1319', 'SBM3', 'PRECISE USTED CUÁL DE LOS SIGUIENTES ENUNCIADOS ES EL CORRECTO: Ley N° 27444 - Ley del Procedimiento Administrativo General', 'EL RECURSO DE APELACIÓN SE INTERPONDRÁ CUANDO LA IMPUGNACIÓN SE SUSTENTE EN DIFERENTE INTERPRETACIÓN DE LAS PRUEBAS PRODUCIDAS.', 'ART. 209', '181892'),
    (1320, 'SUB-1320', 'SBM3', 'DE LOS SIGUIENTES ENUNCIADOS RELATIVOS A LA ACUMULACIÓN DE SOLICITUDES, SEÑALE USTED EL QUE ES CORRECTO:', 'LA ACUMULACIÓN DE PETICIONES O SOLICITUDES TIENE EL PROPÓSITO QUE SE LES TRAMITE EN UN MISMO EXPEDIENTE DE MANERA SIMULTÁNEA.', 'ART. 116', '181893'),
    (1321, 'SUB-1321', 'SBM3', 'PRINCIPIO DE PRESUNCIÓN DE VERACIDAD.- EN LA TRAMITACIÓN DEL PROCEDIMIENTO ADMINISTRATIVO, SE PRESUME QUE LOS DOCUMENTOS Y DECLARACIONES FORMULADOS POR LOS ADMINISTRADOS EN LA FORMA PRESCRITA POR ESTA LEY, RESPONDEN A LA VERDAD DE LOS HECHOS QUE ELLOS AFIRMAN. ESTA PRESUNCIÓN...:', 'ADMITE PRUEBA EN CONTRARIO.', 'TITULO PRELIMINAR ART. IV', '181894'),
    (1322, 'SUB-1322', 'SBM3', 'ART. 143 - RESPONSABILIDAD POR INCUMPLIMIENTO DE PLAZOS.- EL INCUMPLIMIENTO INJUSTIFICADO DE LOS PLAZOS PREVISTOS PARA LAS ACTUACIONES DE LAS ENTIDADES GENERA RESPONSABILIDAD (. ................ ) PARA LA AUTORIDAD OBLIGADA, SIN PERJUICIO DE LA RESPONSABILIDAD CIVIL POR LOS DAÑOS Y PERJUICIOS QUE PUDIERA HABER ACASIONADO: (SEÑALE LA RESPUESTA CORRECTA).', 'DISCIPLINARIA.', 'ART. 143', '181895'),
    (1323, 'SUB-1323', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ PRACTICARSE A MÁS TARDAR DENTRO DEL PLAZO DE 5 DÍAS A PARTIR DE LA EXPEDICIÓN DEL ACTO QUE SE NOTIFIQUE Y DEBERÁ CONTENER:(SEÑALE LO INCORRECTO).', 'LA EXPRESIÓN DE LOS RECURSOS QUE NO PROCEDEN Y LA ENTIDAD ANTE LA CUÁL DEBE PRESENTARSE LA DOCUMENTACIÓN Y EL PLAZO DE CADUCIDAD.', 'ART. 24', '181896'),
    (1324, 'SUB-1324', 'SBM3', 'PRECISE USTED CUÁL ES EL ENUNCIADO CORRECTO QUE ESTABLECE UNO DE LOS DEBERES GENERALES DE LOS ADMINISTRADOS EN EL PROCEDIMIENTO:', 'PRESTAR SU COLABORACIÓN PARA EL PERTINENTE ESCLARECIMIENTO DE LOS HECHOS.', 'ART. 56', '181897'),
    (1325, 'SUB-1325', 'SBM3', 'ORIENTAN AL ADMINISTRADO EN LA PRESENTACIÓN DE SUS SOLICITUDES Y FORMULARIOS, QUEDANDO OBLIGADAS A RECIBIRLOS Y DARLES INGRESO PARA INICIAR O IMPULSAR LOS PROCEDIMIENTOS, SIN QUE EN NINGÚN CASO PUEDA CALIFICAR, NEGAR O DIFERIR SU ADMISIÓN:', 'LAS UNIDADES DE RECEPCIÓN DOCUMENTAL.', 'ART. 124', '181898'),
    (1326, 'SUB-1326', 'SBM3', 'EL TÉRMINO PARA LA INTERPOSICIÓN DE LOS RECURSOS ADMINISTRATIVOS ES DE (15) DÍAS PERENTORIOS, Y DEBERÁN RESOLVERSE EN EL PLAZO DE :', 'TREINTA (30) DÍAS.', 'ART. 207', '181899'),
    (1327, 'SUB-1327', 'SBM3', 'ES UN REQUISITO DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS: (SEÑALE LA RESPUESTA INCORRECTA):', 'FINALIDAD PÚBLICA O PRIVADA.', 'ART. 3', '181900'),
    (1328, 'SUB-1328', 'SBM3', 'ART. 218 - AGOTAMIENTO DE LA VÍA ADMINISTRATIVA.- LOS ACTOS ADMINISTRATIVOS QUE AGOTAN LA VÍA ADMINISTRATIVA PODRÁN SER IMPUGNADAS ANTE EL PODER JUDICIAL, MEDIANTE:', 'PROCESO CONTENCIOSO ADMINISTRATIVO.', 'ART. 218', '181901'),
    (1329, 'SUB-1329', 'SBM3', 'PRECISE CUÁL DE LOS ENUNCIADOS QUE SE ENUMERA A CONTINUACIÓN, CONSTITUYE UN RECURSO ADMINISTRATIVO QUE RECONOCE COMO TAL LA LEY 27444. Ley N° 27444 - Ley del Procedimiento Administrativo General', 'RECURSO DE APELACIÓN.', 'ART. 209', '181902'),
    (1330, 'SUB-1330', 'SBM3', 'PARA MANTENER REUNIDAS TODAS LAS ACTUACIONES PARA RESOLVER, CUÁNTOS EXPEDIENTES PUEDEN ORGANIZARSE PARA LA SOLUCIÓN DE UN MISMO CASO? MARCA LA CORRECTA:', 'SÓLO UN EXPEDIENTE.', 'ART. 150', '181903'),
    (1331, 'SUB-1331', 'SBM3', 'INDIQUE, DE LOS ENUNCIADOS SIGUIENTES, RESPECTO A REQUISITOS DE LOS ESCRITOS.- CUÁL ES EL INCORRECTO:', 'CERTIFICADOS DE ESTUDIO', 'ART. 113', '181904'),
    (1332, 'SUB-1332', 'SBM3', 'DERECHO DE PETICIÓN ADMINISTRATIVA.- CUALQUIER ADMINISTRADO, INDIVIDUAL O COLECTIVAMENTE, PUEDE PROMOVER POR ESCRITO EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO ANTE TODAS Y CUALQUIERA DE LAS ENTIDADES, EJERCIENDO EL DERECHO DE PETICIÓN, RECONOCIDO EN EL ...:', 'ART. 2 INCISO 20.- DE LA CONSTITUCIÓN POLÍTICA DEL ESTADO.', 'ART. 106', '181905'),
    (1333, 'SUB-1333', 'SBM3', 'INDIQUE USTED DE LOS ENUNCIADOS SIGUIENTES CUÁL ES EL CORRECTO, RESPECTO AL CONTENIDO DE LA LEY N 27444:', 'CONTIENE NORMAS COMUNES PARA LAS ACTUACIONES DE LA FUNCIÓN ADMINISTRATIVA DEL ESTADO Y, REGULA TODOS LOS PROCEDIMIENTOS ADMINISTRATIVOS DESARROLLADOS EN LAS ENTIDADES, INCLUYENDO LOS PROCEDIMIENTOS ESPECIALES', 'TITULO PRELIMINAR ART. II', '181906'),
    (1334, 'SUB-1334', 'SBM3', 'EN EL ACTO DE NOTIFICACIÓN : MARCA EL CORRECTO', 'SE ENTREGA COPIA DEL ACTO NOTIFICADO.', 'ART. 21', '181907'),
    (1335, 'SUB-1335', 'SBM3', 'LA AUTORIDAD ORDENARÁ QUE SE REHAGA LA NOTIFICACIÓN, EN EL SIGUIENTE CASO: MARCA LA CORRECTA.', 'QUE SE DEMUESTRE QUE LA NOTIFICACIÓN SE HA REALIZADO SIN LAS FORMALIDADES Y REQUISITOS LEGALES.', 'ART. 26', '181908'),
    (1336, 'SUB-1336', 'SBM3', 'EFICACIA DEL ACTO ADMINISTRATIVO.- EL ACTO ADMINISTRATIVO QUE OTORGA BENEFICIO AL ADMINISTRADO SE ENTIENDE EFICAZ DESDE LA FECHA DE SU EMISIÓN, SALVO: (SEÑALE LA RESPUESTA CORRECTA).', 'DISPOSICIÓN DIFERENTE DEL MISMO ACTO.', 'ART. 16', '181909'),
    (1337, 'SUB-1337', 'SBM3', 'VIGENCIA DE LAS NOTIFICACIONES.- LAS NOTIFICACIONES SURTIRÁN EFECTO CONFORME A LAS SIGUIENTES REGLAS: (SEÑALE EL INCORRECTO)', 'LAS NOTIFICACIONES TELEFÓNICAS: EL MISMO DÍA.', 'ART. 25', '181910'),
    (1338, 'SUB-1338', 'SBM3', 'NOTIFICACIONES DEFECTUOSAS.- LA DESESTIMACIÓN DEL CUESTIONAMIENTO A LA VALIDEZ DE UNA NOTIFICACIÓN, CAUSA QUE DICHA NOTIFICACIÓN: ( SEÑALE LO CORRECTO)', 'OPERE DESDE LA FECHA EN QUE FUE REALIZADA.', 'ART. 26', '181911'),
    (1339, 'SUB-1339', 'SBM3', 'INDEPENDENCIA DE LOS VICIOS DEL ACTO ADMINISTRATIVO.- LOS VICIOS INCURRIDOS EN LA EJECUCIÓN DE UN ACTO ADMINISTRATIVO O EN SU MODIFICACIÓN A LOS ADMINISTRADOS SON:', 'INDEPENDIENTES DE SU VALIDEZ.', 'ART. 15 Ley N° 27444 - Ley del Procedimiento Administrativo General', '181912'),
    (1340, 'SUB-1340', 'SBM3', 'RECURSO DE RECONSIDERACION.- EN LOS CASOS DE ACTOS ADMINISTRATIVOS, EMITIDOS POR ÓRGANOS QUE CONSTITUYEN ÚNICA INSTANCIA: (INDIQUE LA RESPUESTA CORRECTA).', 'NO SE REQUIERE NUEVA PRUEBA.', 'ART. 208', '181913'),
    (1341, 'SUB-1341', 'SBM3', '(. .................. ), ESTIMARÁ EN TODO O EN PARTE O DESESTIMARÁ LAS PRETENSIONES FORMULADAS EN EL MISMO, O DECLARARÁ SU INADMISIÓN.', 'LA RESOLUCIÓN DEL RECURSO.', 'ART. 217', '181914'),
    (1342, 'SUB-1342', 'SBM3', 'CONSERVACIÓN DEL ACTO.- SON ACTOS ADMINISTRATIVOS AFECTADOS POR VICIOS NO TRASCENDENTES LOS SIGUIENTES: (SEÑALE LA INCORRECTA)', 'LA CONTRAVENCIÓN A LA CONSTITUCIÓN, A LAS LEYES O A LAS NORMAS REGLAMENTARIAS.', 'ART. 14', '181915'),
    (1343, 'SUB-1343', 'SBM3', 'LOS PRINCIPIOS DEL PROCEDIMIENTO ADMINISTRATIVO:', 'NO TIENEN CARÁCTER TAXATIVO', 'TITULO PRELIMINAR ART. IV', '181916'),
    (1344, 'SUB-1344', 'SBM3', 'LA CARGA DE LA PRUEBA SE RIGE POR EL PRINCIPIO DE (.....) ESTABLECIDO EN LA PRESENTE LEY.', 'IMPULSO DE OFICIO.', 'ART. 162', '181919'),
    (1345, 'SUB-1345', 'SBM3', 'DE ACUERDO CON EL ARTÍCULO 174 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, ¿CUÁL ES UNA DE LAS ALTERNATIVAS QUE TIENE LA AUTORIDAD ANTE LA OMISIÓN DEL INFORME DENTRO DEL PLAZO SEÑALADO?', 'PRESCINDIR DEL INFORME, DEPENDIENDO DE LAS CIRCUNSTANCIAS DEL CASO Y LA RELACIÓN ADMINISTRATIVA CON EL INFORMANTE.', 'ART. 174', '181921'),
    (1346, 'SUB-1346', 'SBM3', '¿QUIEN TIENE LA CARGA DE LA COMPARECENCIA DE LOS TESTIGOS EN EL LUGAR, FECHA Y HORA FIJADOS?', 'EL PROPONENTE DE LA PRUEBA DE TESTIGOS.', 'ART. 175', '181922'),
    (1347, 'SUB-1347', 'SBM3', 'EN EL MARCO DEL ARTÍCULO 176 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, ¿CUÁL ES EL PROCEDIMIENTO CORRECTO PARA QUE LOS ADMINISTRADOS PROPONGAN LA INTERVENCIÓN DE PERITOS DURANTE UN PROCEDIMIENTO ADMINISTRATIVO?', 'LOS ADMINISTRADOS PUEDEN PROPONER LA DESIGNACIÓN DE PERITOS A SU COSTA, DEBIENDO EN EL MISMO MOMENTO SEÑALAR LOS ASPECTOS TÉCNICOS SOBRE LOS CUALES DEBEN PRONUNCIARSE', 'ART. 176', '181923'),
    (1348, 'SUB-1348', 'SBM3', 'EN RELACIÓN AL DEBER DE LOS TERCEROS DE COLABORAR EN ACTUACIONES PROBATORIAS EN EL PROCEDIMIENTO ADMINISTRATIVO, SEGÚN EL ARTÍCULO 179, EL CUMPLIMIENTO DE ESTE DEBER:', 'SE ENCUENTRA SUPEDITADO AL RESPETO DE LOS DERECHOS CONSTITUCIONALES DE LOS TERCEROS INVOLUCRADOS', 'ART. 179', '181924'),
    (1349, 'SUB-1349', 'SBM3', 'LOS ERRORES MATERIAL O ARITMÉTICO EN LOS ACTOS ADMINISTRATIVOS (............ ), EN CUALQUIER MOMENTO, DE OFICIO O A INSTANCIA DE LOS ADMINISTRADOS, SIEMPRE QUE NO SE ALTERE LO SUSTANCIAL DE SU CONTENIDO NI EL SENTIDO DE LA DECISIÓN.', 'PUEDEN SER RECTIFICADOS CON EFECTO RETROACTIVO.', 'ART. 201', '181925'),
    (1350, 'SUB-1350', 'SBM3', 'RECURSOS ADMINISTRATIVOS.- CONSTATADA LA EXISTENCIA DE UNA CAUSAL DE NULIDAD, LA AUTORIDAD, ADEMÁS DE LA DECLARACIÓN DE NULIDAD, RESOLVERÁ SOBRE EL FONDO DEL ASUNTO, DE CONTARSE CON LOS ELEMENTOS SUFICIENTES PARA ELLO. CUANDO NO SEA POSIBLE PRONUNCIARSE SOBRE EL FONDO DEL ASUNTO, SE DISPONDRÁ: Ley N° 27444 - Ley del Procedimiento Administrativo General', 'LA REPOSICIÓN DEL PROCEDIMIENTO AL MOMENTO EN QUE EL VICIO SE PRODUJO.', 'ART. 217', '181926'),
    (1351, 'SUB-1351', 'SBM3', 'EN LA RESOLUCIÓN QUE PONGA FIN AL PROCEDIMIENTO SANCIONADOR NO SE PODRÁN ACEPTAR HECHOS DISTINTOS DE LOS DETERMINADOS EN EL CURSO DEL PROCEDIMIENTO, CON INDEPENDENCIA DE SU DIFERENTE VALORACIÓN JURÍDICA. LA RESOLUCIÓN SERÁ EJECUTIVA CUANDO:', 'PONGA FIN A LA VÍA ADMINISTRATIVA.', 'ART. 237', '181927'),
    (1352, 'SUB-1352', 'SBM3', 'RESPECTO A LAS RESPONSABILIDADES DE LA ADMINISTRACIÓN PÚBLICA SEÑALE LA RESPUESTA CORRECTA:', 'LA DECLARATORIA DE NULIDAD DE UN ACTO ADMINISTRATIVO EN SEDE ADMINISTRATIVA O POR RESOLUCIÓN JUDICIAL NO PRESUPONE NECESARIAMENTE DERECHO A LA INDEMNIZACIÓN.', 'ART. 238', '181928'),
    (1353, 'SUB-1353', 'SBM3', 'DE ACUERDO CON EL ARTÍCULO 124 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, RESPECTO A LAS FUNCIONES DE LAS UNIDADES DE RECEPCIÓN DOCUMENTAL, ¿CUÁL ES LA LIMITACIÓN MÁS RELEVANTE IMPUESTA A DICHAS UNIDADES EN EL MARCO DE LA ADMISIÓN DE SOLICITUDES PRESENTADAS POR LOS ADMINISTRADOS?', 'ESTÁN OBLIGADAS A RECIBIR Y DAR INGRESO A LAS SOLICITUDES, SIN PODER CALIFICAR, NEGAR O DIFERIR SU ADMISIÓN BAJO NINGÚN SUPUESTO', 'ART. 124', '181929'),
    (1354, 'SUB-1354', 'SBM3', 'INICIACIÓN DEL PROCEDIMIENTO.- CUANDO SEA INGRESADA UNA SOLICITUD QUE SE ESTIMA COMPETENCIA DE OTRA ENTIDAD, LA ENTIDAD RECEPTORA DEBE REMITIRLA, EN EL (..... ), A AQUELLA QUE CONSIDERE COMPETENTE, COMUNICANDO DICHA DECISIÓN AL ADMINISTRADO.', 'TÉRMINO DE LA DISTANCIA.', 'ART. 130', '181930'),
    (1355, 'SUB-1355', 'SBM3', 'DEL PROCEDIMIENTO ADMINISTRATIVO.- AL VENCIMIENTO DE UN (. ... ) PARA REALIZAR UNA ACTUACIÓN O EJERCER UNA FACULTAD PROCESAL, PREVIO APERCIBIMIENTO, LA ENTIDAD DECLARA DECAÍDO EL DERECHO AL CORRESPONDIENTE ACTO, NOTIFICANDO LA DECISIÓN.', 'PLAZO IMPRORROGABLE.', 'ART. 140', '181931'),
    (1356, 'SUB-1356', 'SBM3', 'DE ACUERDO AL ARTÍCULO 140 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, ¿CUÁNDO SE CONSIDERA VENCIDO UN PLAZO FIJADO PARA LA REALIZACIÓN DE UNA ACTUACIÓN ADMINISTRATIVA?', 'EL PLAZO VENCE AL ÚLTIMO MOMENTO DEL DÍA HÁBIL SEÑALADO, O ANTICIPADAMENTE SI LA ACTUACIÓN PARA LA QUE FUE ESTABLECIDO SE CUMPLE ANTES.', 'ART. 140', '181932'),
    (1357, 'SUB-1357', 'SBM3', 'DEL PROCEDIMIENTO ADMINISTRATIVO.- RESPECTO AL IMPULSO DEL PROCEDIMIENTO, SEÑALE LA RESPUESTA CORRECTA:', 'LA AUTORIDAD COMPETENTE DEBE ADOPTAR LAS MEDIDAS OPORTUNAS PARA ELIMINAR CUALQUIER IRREGULARIDAD PRODUCIDA.', 'ART. 145', '181933'),
    (1358, 'SUB-1358', 'SBM3', 'SEGÚN EL ARTÍCULO 146 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL (LEY 27444), ¿EN CUÁL DE LOS SIGUIENTES ESCENARIOS UNA MEDIDA CAUTELAR DICTADA EN UN PROCEDIMIENTO ADMINISTRATIVO CADUCA DE PLENO DERECHO?', 'CUANDO SE EMITE LA RESOLUCIÓN QUE PONE FIN AL PROCEDIMIENTO ADMINISTRATIVO', 'ART. 146', '181934'),
    (1359, 'SUB-1359', 'SBM3', 'EN UNA SOLA DECISIÓN SE DISPONDRÁ EL CUMPLIMIENTO DE TODOS LOS TRÁMITES NECESARIOS QUE POR SU NATURALEZA CORRESPONDA, SIEMPRE Y CUANDO NO SE ENCUENTREN ENTRE SÍ SUCESIVAMENTE SUBORDINADOS EN SU CUMPLIMIENTO, Y SE CONCENTRARÁN EN UN MISMO ACTO TODAS LAS DILIGENCIAS Y ACTUACIONES DE PRUEBAS POSIBLES, PROCURANDO QUE EL DESARROLLO DEL PROCEDIMIENTO SE REALICE EN EL MENOR NÚMERO DE ACTOS PROCESALES. EL REFERIDO PÁRRAFO CONSTITUYE UNA REGLA PARA ASEGURAR EL CUMPLIMIENTO DEL PRINCIPIO DE:', 'CELERIDAD.', 'ART. 148', '181935'),
    (1360, 'SUB-1360', 'SBM3', 'EN EL IMPULSO Y TRAMITACIÓN DE CASOS DE UNA MISMA NATURALEZA, SE SIGUE RIGUROSAMENTE EL ORDEN DE INGRESO, Y SE RESUELVEN CONFORME LO VAYA PERMITIENDO SU ESTADO, DANDO CUENTA AL SUPERIOR DE LOS MOTIVOS DE DEMORA EN EL CUMPLIMIENTO DE LOS PLAZOS DE LEY, QUE NO PUEDAN SER REMOVIDOS DE OFICIO. EL REFERIDO PÁRRAFO CONSTITUYE UNA REGLA PARA ASEGURAR EL CUMPLIMIENTO DEL PRINCIPIO DE:', 'CELERIDAD.', 'ART. 148', '181936'),
    (1361, 'SUB-1361', 'SBM3', 'EN NINGÚN CASO LA AUTORIDAD PODRÁ ALEGAR DEFICIENCIAS DEL ADMINISTRADO NO ADVERTIDAS A LA PRESENTACIÓN DE LA SOLICITUD, COMO FUNDAMENTO PARA DENEGAR SU PRETENSIÓN. EL REFERIDO PÁRRAFO CONSTITUYE UNA REGLA PARA ASEGURAR EL CUMPLIMIENTO DEL PRINCIPIO DE:', 'CELERIDAD.', 'ART. 148', '181937'),
    (1362, 'SUB-1362', 'SBM3', 'DEL PROCEDIMIENTO ADMINISTRATIVO.- LOS EXPEDIENTES SON COMPAGINADOS SIGUIENDO EL ORDEN REGULAR DE LOS DOCUMENTOS QUE LO INTEGRAN, FORMANDO CUERPOS CORRELATIVOS QUE NO EXCEDAN DE (.......), SALVO CUANDO TAL LÍMITE OBLIGARA A DIVIDIR ESCRITOS O DOCUMENTOS QUE CONSTITUYAN UN SOLO TEXTO, EN CUYO CASO SE MANTENDRÁ SU UNIDAD.', 'DOSCIENTOS FOLIOS.', 'ART. 152', '181938'),
    (1363, 'SUB-1363', 'SBM3', '¿EN QUÉ MOMENTO, LOS ADMINISTRADOS PUEDEN FORMULAR QUEJA CONTRA LOS DEFECTOS DE TRAMITACIÓN Y, EN ESPECIAL, LOS QUE SUPONGAN PARALIZACIÓN, INFRACCIÓN DE LOS PLAZOS ESTABLECIDOS LEGALMENTE, INCUMPLIMIENTO DE LOS DEBERES FUNCIONALES U OMISIÓN DE TRÁMITES QUE DEBEN SER SUBSANADOS?', 'EN CUALQUIER MOMENTO.', 'ART. 158 Ley N° 27444 - Ley del Procedimiento Administrativo General', '181939'),
    (1364, 'SUB-1364', 'SBM3', 'CONTINUACIÓN DEL PROCEDIMIENTO.- LUEGO DE RESUELTO EL CONFLICTO DE COMPETENCIA, EL ÓRGANO QUE RESULTE COMPETENTE PARA CONOCER EL ASUNTO CONTINÚA EL PROCEDIMIENTO SEGÚN SU ESTADO Y CONSERVA TODO LO ACTUADO, SALVO AQUELLO QUE NO SEA (. ).', 'JURÍDICAMENTE POSIBLE.', 'ART. 87', '181940'),
    (1365, 'SUB-1365', 'SBM3', 'AUTORIDADES DE LOS ÓRGANOS COLEGIADOS.- ¿QUIEN TIENE A CARGO ASEGURAR LA REGULARIDAD DE LAS DELIBERACIONES Y EJECUTAR SUS ACUERDOS.?', 'EL PRESIDENTE DEL ÓRGANO COLEGIADO.', 'ART. 96', '181941'),
    (1366, 'SUB-1366', 'SBM3', 'AUTORIDADES DE LOS ÓRGANOS COLEGIADOS.- CADA ÓRGANO COLEGIADO DE LAS ENTIDADES ES REPRESENTADO POR UN (. ...............), A CARGO DE ASEGURAR LA REGULARIDAD DE LAS DELIBERACIONES Y EJECUTAR SUS ACUERDOS, Y CUENTA CON UN SECRETARIO, A CARGO DE PREPARAR LA AGENDA, LLEVAR, ACTUALIZAR Y CONSERVAR LAS ACTAS DE LAS SESIONES, COMUNICAR LOS ACUERDOS, OTORGAR COPIAS Y DEMÁS ACTOS PROPIOS DE LA NATURALEZA DEL CARGO.', 'PRESIDENTE.', 'ART. 96', '181942'),
    (1367, 'SUB-1367', 'SBM3', '( .....), ES PROMOVIDO DE OFICIO POR EL ÓRGANO COMPETENTE O INSTANCIA DEL ADMINISTRADO, SALVO QUE POR DISPOSICIÓN LEGAL O POR SU FINALIDAD CORRESPONDA SER INICIADO EXCLUSIVAMENTE DE OFICIO O A INSTANCIA DEL INTERESADO.', 'EL PROCEDIMIENTO ADMINISTRATIVO.', 'ART. 103', '181943'),
    (1368, 'SUB-1368', 'SBM3', 'FRENTE A UN ACTO QUE SUPONE QUE VIOLA, AFECTA, DESCONOCE O LESIONA UN DERECHO O UN INTERÉS LEGÍTIMO, PROCEDE (. ...) EN LA VÍA ADMINISTRATIVA EN LA FORMA PREVISTA EN ESTA LEY, PARA QUE SEA REVOCADO, MODIFICADO, ANULADO O SEAN SUSPENDIDOS SUS EFECTOS.', 'SU CONTRADICCIÓN.', 'ART. 109', '181944'),
    (1369, 'SUB-1369', 'SBM3', 'EN RELACIÓN AL ARTÍCULO 61 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL (LEY 27444), RESPECTO A LA FUENTE DE LA COMPETENCIA DE LAS ENTIDADES ADMINISTRATIVAS, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES DESCRIBE CORRECTAMENTE EL ORIGEN Y REGULACIÓN DE DICHA COMPETENCIA?', 'LA COMPETENCIA DE LAS ENTIDADES DEVIENE ÚNICAMENTE DE LA CONSTITUCIÓN Y LA LEY, Y ES REGLAMENTADA POR NORMAS ADMINISTRATIVAS QUE SE DERIVAN DE DICHAS FUENTES', 'ART. 61', '181945'),
    (1370, 'SUB-1370', 'SBM3', 'DE ACUERDO CON EL ARTÍCULO 73 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL (LEY 27444), RESPECTO A LA SUPLENCIA DE LOS TITULARES DE ÓRGANOS ADMINISTRATIVOS, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA SOBRE EL PROCESO DE SUPLENCIA TEMPORAL EN CASO DE VACANCIA O AUSENCIA JUSTIFICADA?', 'LA SUPLENCIA DE LOS TITULARES DE ÓRGANOS ADMINISTRATIVOS, EN CASO DE VACANCIA O AUSENCIA JUSTIFICADA, DEBE SER DISPUESTA POR QUIEN TIENE COMPETENCIA PARA REALIZAR EL NOMBRAMIENTO DE DICHO TITULAR.', 'ART. 73', '181946'),
    (1371, 'SUB-1371', 'SBM3', 'SEGÚN EL ARTÍCULO 79 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, ¿CUÁL ES LA CONSECUENCIA PRINCIPAL RESPECTO DE LAS COSTAS CUANDO UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA SOLICITA LA COLABORACIÓN DE OTRA ENTIDAD?', 'NO SE GENERA EL PAGO DE TASAS, DERECHOS ADMINISTRATIVOS O DE CUALQUIER OTRO CONCEPTO QUE IMPLIQUE PAGO ALGUNO ENTRE ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA.', 'ART. 79', '181947'),
    (1372, 'SUB-1372', 'SBM3', 'EN TODO CONFLICTO DE COMPETENCIA, EL ÓRGANO A QUIEN SE REMITE EL EXPEDIENTE DICTA RESOLUCIÓN IRRECURRIBLE DENTRO DEL PLAZO DE (. ..).', 'CUATRO DÍAS.', 'ART. 85', '181948'),
    (1373, 'SUB-1373', 'SBM3', 'SEGÚN EL ARTÍCULO 86 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, ¿QUIÉN ES COMPETENTE PARA RESOLVER LOS CONFLICTOS POSITIVOS O NEGATIVOS DE COMPETENCIA DENTRO DE UNA MISMA ENTIDAD ADMINISTRATIVA CUANDO EXISTEN DIVERSAS AUTORIDADES INVOLUCRADAS?', 'EL SUPERIOR JERÁRQUICO COMÚN DE LAS AUTORIDADES EN CONFLICTO', 'ART. 86', '181949'),
    (1374, 'SUB-1374', 'SBM3', 'SI DEBIERA NOTIFICARSE A MÁS DE (...) PERSONAS QUE HAN PLANTEADO UNA SOLA SOLICITUD CON DERECHO COMÚN, LA NOTIFICACIÓN SE HARÁ CON QUIEN ENCABEZA EL ESCRITO INICIAL, INDICÁNDOLE QUE TRASMITA LA DECISIÓN A SUS COINTERESADOS.', 'DIEZ.', 'ART. 22', '181950'),
    (1375, 'SUB-1375', 'SBM3', 'SEGÚN EL ARTÍCULO 51 DE LA LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL (LEY 27444), ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES DEFINE CORRECTAMENTE QUIÉNES SON CONSIDERADOS ADMINISTRADOS RESPECTO DE UN PROCEDIMIENTO ADMINISTRATIVO CONCRETO?', 'LOS QUE PROMUEVEN EL PROCEDIMIENTO Y ADEMÁS QUIENES, AUN SIN INICIARLO, POSEAN DERECHOS O INTERESES LEGÍTIMOS QUE PUEDAN SER AFECTADOS POR LA DECISIÓN', 'ART. 51', '181951'),
    (1376, 'SUB-1376', 'SBM3', 'LOS ACTOS ADMINISTRATIVOS DEBERÁN EXPRESARSE POR ESCRITO, SALVO QUE POR LA NATURALEZA Y CIRCUNSTANCIA DEL CASO, EL ORDENAMIENTO JURÍDICO HAYA PREVISTO OTRA FORMA, SIEMPRE QUE PERMITA TENER CONSTANCIA DE SU EXISTENCIA, SE REFIERE A UNA:', 'FORMA DE LOS ACTOS ADMINISTRATIVOS.', 'ART. 4', '181952'),
    (1377, 'SUB-1377', 'SBM3', 'ES VÁLIDO EL ACTO ADMNINISTRATIVO DICTADO CONFORME AL ORDENAMIENTO JURÍDICO; SE REFIERE A:', 'VALIDEZ DEL ACTO ADMINISTRATIVO. Ley N° 27444 - Ley del Procedimiento Administrativo General', 'ART. 8', '181953'),
    (1378, 'SUB-1378', 'SBM3', 'LA NULIDAD DE UN ACTO SÓLO IMPLICA LA DE LOS SUCESIVOS EN EL PROCEDIMIENTO CUANDO ESTÉN VINCULADOS A ÉL; SE REFIERE A:', 'ALCANCES DE LA NULIDAD.', 'ART. 13', '181954'),
    (1379, 'SUB-1379', 'SBM3', 'LA AUTORIDAD PODRÁ DISPONER EN EL MISMO ACTO ADMINISTRATIVO QUE TENGA EFICACIA ANTICIPADA A SU EMISIÓN, SÓLO SI FUERA MÁS FAVORABLE A LOS ADMINISTRADOS, Y SIEMPRE QUE NO LESIONE DERECHOS FUNDAMENTALES O INTERESES DE BUENA FE LEGALMENTE PROTEGIDOS A TERCEROS Y QUE EXISTIERA EN LA FECHA A LA QUE PRETENDA RETROTRAERSE LA EFICACIA DEL ACTO EL SUPUESTO DE HECHO JUSTIFICATIVO PARA SU ADOPCIÓN; SE REFIERE A LA:', 'EFICACIA ANTICIPADA DEL ACTO ADMINISTRATIVO.', 'ART. 17', '181955'),
    (1380, 'SUB-1380', 'SBM3', 'SE HARÁ EN EL DOMICILIO QUE CONSTE EN EL EXPEDIENTE, O EN EL ÚLTIMO DOMICILIO QUE LA PERSONA A QUIÉN DEBA NOTIFICAR HAYA SEÑALADO ANTE EL ÓRGANO ADMNINISTRATIVO EN OTRO PROCEDIMIENTO ANÁLOGO EN LA PROPIA ENTIDAD DENTRO DEL ÚLTIMO AÑO; SE REFIERE A:', 'LA NOTIFICACIÓN PERSONAL.', 'ART. 21', '181956'),
    (1381, 'SUB-1381', 'SBM3', 'CONJUNTO DE ACTOS Y DILIGENCIAS TRÁMITADOS EN LAS ENTIDADES, CONDUCENTES A LA EMISIÓN DE UN ACTO ADMINISTRATIVO QUE PRODUZCA EFECTOS JURÍDICOS INDIVIDUALES O INDIVIDUALIZABLES SOBRE INTERESES, OBLIGACIONES O DERECHOS DE LOS ADMINISTRADOS; SE REFIERE A:', 'PROCEDIMIENTOS ADMINISTRATIVOS.', 'ART. 29', '181957'),
    (1382, 'SUB-1382', 'SBM3', 'EL PLAZO QUE TRANSCURRA DESDE EL INICIO DE UN PROCEDIMEINTO ADMINISTRATIVO DE EVALUACIÓN PREVIA HASTA QUE SEA DICTADA LA RESOLUCIÓN RESPECTIVA, NO PUEDE EXCEDER DE:', 'TREINTA (30) DÍAS HÁBILES, SALVO QUE POR LEY O DECRETO LEGISLATIVO SE ESTABLEZCAN PROCEDIMIENTOS CUYO CUMPLIMIENTO REQUIERA UNA DURACIÓN MAYOR. Ley N° 27444 - Ley del Procedimiento Administrativo General', 'ART. 35', '181958'),
    (1383, 'SUB-1383', 'SBM3', 'SOLAMENTE SERÁN INCLUIDOS COMO REQUISITOS EXIGIDOS PARA LA REALIZACIÓN DE CADA PROCEDIMIENTO ADMINISTRATIVO AQUELLOS QUE RAZONABLEMENTE SEAN INDISPENSABLES PARA OBTENER EL PRONUNCIAMIENTO CORRESPONDIENTE, ATENDIENDO ADEMÁS A SUS COSTOS Y BENEFICIOS; SE REFIERE A:', 'CONSIDERACIONES PARA ESTRUCTURAR EL PROCEDIMIENTO.', 'ART. 39', '181959'),
    (1384, 'SUB-1384', 'SBM3', 'SON CONSIDERADOS DOCUMENTOS PÚBLICOS AQUELLOS EMITIDOS:', 'VÁLIDAMENTE POR LOS ÓRGANOS DE LAS ENTIDADES.', 'ART. 43', '181960'),
    (1385, 'SUB-1385', 'SBM3', 'EL CITATORIO SE RIGE POR EL RÉGIMEN COMÚN DE LA NOTIFICACIÓN; ES UNA:', 'FORMALIDAD DE LA COMPARECENCIA.', 'ART. 59', '181961'),
    (1386, 'SUB-1386', 'SBM3', 'LA REALIZACIÓN DE ACTIVIDADES CON CARÁCTER MATERIAL, TÉCNICO O DE SERVICIOS DE COMPETENCIA DE UN ÓRGANO PUEDE SER ENCARGADA A OTROS ÓRGANOS O ENTIDADES POR RAZONES DE EFICACIA, O CUANDO LA ENCARGADA POSEA LOS MEDIOS IDÓNEOS PARA SU DESEMPEÑO POR SÍ MISMA; SE REFIERE A:', 'ENCARGO DE GESTIÓN.', 'ART. 71', '181962'),
    (1387, 'SUB-1387', 'SBM3', 'NO GENERA PAGO DE TASAS, DERECHOS ADMINISTRATIVOS O DE CUALQUIER OTRO CONCEPTO QUE IMPLIQUE PAGO ALGUNO, ENTRE ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA:', 'LA SOLICITUD DE COLABORACIÓN.', 'ART. 79', '181963'),
    (1388, 'SUB-1388', 'SBM3', 'EL ACTO ADMINISTRATIVO ES EFICAZ A PARTIR DE QUE LA NOTIFICACIÓN LEGALMENTE REALIZADA PRODUCE:', 'SUS EFECTOS.', 'ART. 16', '181964'),
    (1389, 'SUB-1389', 'SBM3', 'UNA MODALIDAD ACCESORIA NO PUEDE SER APLICADA CONTRA EL FIN PERSEGUIDO POR:', 'EL ACTO ADMINISTRATIVO.', 'ART. 2', '181965'),
    (1390, 'SUB-1390', 'SBM3', 'EL ACTO ADMINISTRATIVO DEBE SER DEBIDAMENTE MOTIVADO EN PROPORCIÓN AL CONTENIDO Y CONFORME AL:', 'ORDENAMIENTO JURÍDICO.', 'ART. 3', '181966'),
    (1391, 'SUB-1391', 'SBM3', 'DEBE SER EXPRESA, MEDIANTE UNA RELACIÓN CONCRETA Y DIRECTA DE LOS HECHOS PROBADOS RELEVANTES DEL CASO ESPECÍFICO, Y LA EXPOSICIÓN DE LAS RAZONES JURÍDICAS Y NORMATIVAS QUE CON REFERENCIA DIRECTA A LOS ANTERIORES JUSTIFICAN EL ACTO ADOPTADO. CORRESPONDE A:', 'LA MOTIVACIÓN.', 'ART. 6', '181967'),
    (1392, 'SUB-1392', 'SBM3', 'TODO ACTO ADMINISTRATIVO, SE CONSIDERA VÁLIDO EN TANTO SU PRETENDIDA NULIDAD NO SEA DECLARADA POR AUTORIDAD ADMINISTRATIVA O JURISDICCIONAL SEGÚN CORRESPONDA; SE REFIERE A:', 'PRESUNCIÓN DE VALIDEZ.', 'ART. 9', '181968'),
    (1393, 'SUB-1393', 'SBM3', 'LOS ACTOS ADMINISTRATIVOS QUE SEAN CONSECUTIVOS DE INFRACCIÓN PENAL, O QUE SE DICTEN COMO CONSECUENCIA DE LA MISMA, ES UNA DE LAS:', 'CAUSALES DE NULIDAD.', 'ART. 10', '181969'),
    (1394, 'SUB-1394', 'SBM3', 'EL ACTO CUYO CONTENIDO SEA IMPRECISO O INCONGRUENTE CON LAS CUESTIONES SURGIDAS EN LA MOTIVACIÓN; ES UNO DE LOS:', 'ACTOS ADMINISTRATIVOS AFECTADOS POR VICIOS NO TRASCENDENTES.', 'ART. 14', '181970'),
    (1395, 'SUB-1395', 'SBM3', 'LAS COMUNICACIONES ENTRE LOS ÓRGANOS ADMINISTRATIVOS AL INTERIOR DE UNA ENTIDAD SERÁN EFECTUADAS DIRECTAMENTE:', 'EVITANDO LA INTERVENCIÓN DE OTROS ÓRGANOS.', 'ART. 28', '181971'),
    (1396, 'SUB-1396', 'SBM3', 'ANTE LAS ENTIDADES, LAS PERSONAS QUE GOZAN DE CAPACIDAD JURÍDICA CONFORME A LAS LEYES:', 'TIENEN CAPACIDAD PROCESAL.', 'ART. 52', '181972'),
    (1397, 'SUB-1397', 'SBM3', 'LAS PERSONAS JURÍDICAS PUEDEN INTERVENIR EN EL PROCEDIMIENTO A TRAVÉS DE SUS REPRESENTANTES LEGALES, QUIENES ACTÚAN PREMUNIDOS DE:', 'LOS RESPECTIVOS PODERES.', 'ART. 53', '181973'),
    (1398, 'SUB-1398', 'SBM3', 'ES COMPETENTE PARA REALIZAR LAS TAREAS MATERIALES INTERNAS NECESARIAS PARA EL EFICIENTE CUMPLIMIENTO DE SU EMISIÓN Y OBJETIVOS, ASÍ COMO PARA LA DISTRIBUCIÓN DE LAS ATRIBUCIONES QUE SE ENCUENTREN COMPRENDIDAS DENTRO DE SU COMPETENCIA:', 'TODA ENTIDAD.', 'ART. 61', '181974'),
    (1399, 'SUB-1399', 'SBM3', 'NO PUEDE SER CAMBIADA, ALTERADA O MODIFICADA LA COMPETENCIA DE LAS ENTIDADES CONSAGRADAS:', 'EN LA CONSTITUCIÓN.', 'ART. 65', '181975'),
    (1400, 'SUB-1400', 'SBM3', 'TENDRÁ SIEMPRE LA OBLIGACIÓN DE VIGILAR LA GESTIÓN DEL DELEGADO, Y PODRÁ SER RESPONSABLE CON ÉSTE POR CULPA EN LA VIGILANCIA:', 'EL DELEGANTE.', 'ART. 68', '181976')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

