    ('SUB-1357', 'B', 'LA AUTORIDAD COMPETENTE, PREVIO PEDIDO DE PARTE, DEBE SUPERAR CUALQUIER OBSTÁCULO QUE SE OPONGA A REGULAR TRAMITACIÓN DEL PROCEDIMIENTO.', FALSE, 2),
    ('SUB-1357', 'C', 'LA AUTORIDAD COMPETENTE, PREVIO PEDIDO DE PARTE, DEBE DETERMINAR LA NORMA APLICABLE AL CASO AUN CUANDO NO HAYA SIDO INVOCADA O FUERE ERRÓNEA LA CITA LEGAL.', FALSE, 3),
    ('SUB-1357', 'D', 'LA AUTORIDAD COMPETENTE, PREVIO PEDIDO DE PARTE, DEBE EVITAR EL ENTORPECIMIENTO O DEMORA A CAUSA DE DILIGENCIAS INNECESARIAS O MERAMENTE FORMALES.', FALSE, 4),
    ('SUB-1357', 'E', 'LA AUTORIDAD COMPETENTE DEBE ADOPTAR LAS MEDIDAS OPORTUNAS PARA ELIMINAR CUALQUIER IRREGULARIDAD PRODUCIDA.', TRUE, 5),
    ('SUB-1358', 'A', 'CUANDO SE EMITE LA RESOLUCIÓN QUE PONE FIN AL PROCEDIMIENTO ADMINISTRATIVO', TRUE, 1),
    ('SUB-1358', 'B', 'CUANDO TRANSCURRE EL PLAZO FIJADO PARA LA EJECUCIÓN DE LA MEDIDA CAUTELAR.', FALSE, 2),
    ('SUB-1358', 'C', 'CUANDO EL ADMINISTRADO SOLICITA EXPRESAMENTE LA CADUCIDAD DE LA MEDIDA Y ESTO ES ACEPTADO POR LA AUTORIDAD', FALSE, 3),
