    ('SUB-1369', 'A', 'LA COMPETENCIA DE LAS ENTIDADES ADMINISTRATIVAS PUEDE ESTABLECERSE VÁLIDAMENTE MEDIANTE ACUERDOS MUNICIPALES Y RESOLUCIONES ADMINISTRATIVAS DE CARÁCTER GENERAL A FALTA DE DISPOSICIÓN CONSTITUCIONAL O LEGAL.', FALSE, 1),
    ('SUB-1369', 'B', 'LA COMPETENCIA DE LAS ENTIDADES TIENE SU ORIGEN DIRECTO EN LA PRÁCTICA ADMINISTRATIVA Y LA COSTUMBRE, Y PUEDE SER RECONOCIDA POR REGLAMENTOS EMITIDOS POR LA ADMINISTRACIÓN CENTRAL.', FALSE, 2),
    ('SUB-1369', 'C', 'LA COMPETENCIA DE LAS ENTIDADES DEVIENE ÚNICAMENTE DE LA CONSTITUCIÓN Y LA LEY, Y ES REGLAMENTADA POR NORMAS ADMINISTRATIVAS QUE SE DERIVAN DE DICHAS FUENTES', TRUE, 3),
    ('SUB-1369', 'D', 'LAS ENTIDADES ADQUIEREN COMPETENCIA PRINCIPALMENTE DE LOS TRATADOS INTERNACIONALES RATIFICADOS POR EL ESTADO, EN CUYO CASO LA LEY SOLO TIENE FUNCIÓN INTERPRETATIVA.', FALSE, 4),
    ('SUB-1369', 'E', 'EL EJERCICIO DE COMPETENCIA DEVIENE VÁLIDO SIEMPRE QUE PROVENGA DE UNA NORMA REGLAMENTARIA EMITIDA POR LA ENTIDAD INVOLUCRADA, SIN NECESIDAD DE FUNDAMENTO LEGAL EXPLÍCITO.', FALSE, 5),
    ('SUB-1370', 'A', 'LA SUPLENCIA SOLO PROCEDE ANTE LA AUSENCIA DEL TITULAR, EXCLUYENDO CASOS DE VACANCIA DEFINITIVA.', FALSE, 1),
    ('SUB-1370', 'B', 'LA SUPLENCIA TEMPORAL ES AUTOMÁTICAMENTE EJERCIDA POR EL SERVIDOR CON MAYOR ANTIGÜEDAD EN LA ENTIDAD, SIN NECESIDAD DE DESIGNACIÓN.', FALSE, 2),
    ('SUB-1370', 'C', 'LA SUPLENCIA TEMPORAL CORRESPONDE ÚNICAMENTE AL SUBALTERNO INMEDIATO DEL TITULAR, SIGUIENDO EL ORDEN JERÁRQUICO DEL REGLAMENTO INTERNO.', FALSE, 3),
    ('SUB-1370', 'D', 'LA SUPLENCIA DE LOS TITULARES DE ÓRGANOS ADMINISTRATIVOS, EN CASO DE VACANCIA O AUSENCIA JUSTIFICADA, DEBE SER DISPUESTA POR QUIEN TIENE COMPETENCIA PARA REALIZAR EL NOMBRAMIENTO DE DICHO TITULAR.', TRUE, 4),
    ('SUB-1370', 'E', 'LA SUPLENCIA SOLO PUEDE DISPONERSE SI LA VACANCIA ES PRODUCTO DE UNA SANCIÓN ADMINISTRATIVA VIGENTE.', FALSE, 5),
    ('SUB-1371', 'A', 'LA ENTIDAD QUE SOLICITA LA COLABORACIÓN DEBE ASUMIR LOS COSTOS ADMINISTRATIVOS Y TASAS QUE ELLO OCASIONE.', FALSE, 1),
    ('SUB-1371', 'B', 'LA ENTIDAD QUE RECIBE LA SOLICITUD PUEDE EXIGIR EL PAGO DE DERECHOS ADMINISTRATIVOS SI ASÍ LO CONSIDERA PERTINENTE.', FALSE, 2),
    ('SUB-1371', 'C', 'LA SOLICITUD DE COLABORACIÓN SÍ PUEDE GENERAR EL PAGO DE TASAS, PERO ÚNICAMENTE SI EXISTE UNA DISPOSICIÓN EXPRESA EN UNA REGLAMENTACIÓN INTERNA.', FALSE, 3),
    ('SUB-1371', 'D', 'NO SE GENERA EL PAGO DE TASAS, DERECHOS ADMINISTRATIVOS O DE CUALQUIER OTRO CONCEPTO QUE IMPLIQUE PAGO ALGUNO ENTRE ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA.', TRUE, 4),
    ('SUB-1371', 'E', 'EL PAGO DE CUALQUIER CONCEPTO QUEDARÁ A DISCRECIÓN DEL ÓRGANO ADMINISTRATIVO SUPERIOR A AMBAS ENTIDADES.', FALSE, 5),
