    ('SUB-1375', 'A', 'SOLAMENTE QUIENES INICIAN UN PROCEDIMIENTO ADMINISTRATIVO PUEDEN SER CONSIDERADOS ADMINISTRADOS, SIN IMPORTAR LA AFECTACIÓN DE INTERESES DE TERCEROS.', FALSE, 1),
    ('SUB-1375', 'B', 'SOLO LAS PERSONAS JURÍDICAS, YA QUE SOLO ELLAS PUEDEN OSTENTAR DERECHOS COLECTIVOS ANTE LA ADMINISTRACIÓN PÚBLICA', FALSE, 2),
    ('SUB-1375', 'C', 'LOS QUE PROMUEVEN EL PROCEDIMIENTO Y ADEMÁS QUIENES, AUN SIN INICIARLO, POSEAN DERECHOS O INTERESES LEGÍTIMOS QUE PUEDAN SER AFECTADOS POR LA DECISIÓN', TRUE, 3),
    ('SUB-1375', 'D', 'CUALQUIER PERSONA NATURAL O JURÍDICA, INDEPENDIENTEMENTE DE ESTAR INVOLUCRADOS EN EL PROCEDIMIENTO O DE SER AFECTADOS POR LA DECISIÓN ADMINISTRATIVA', FALSE, 4),
