INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1401 a 1500
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1401, 'SUB-1401', 'SBM3', 'EN CASO DE SUSCITARSE CONFLICTO NEGATIVO DE COMPETENCIA, EL EXPEDIENTE ES ELEVADO AL ÓRGANO INMEDIATO SUPERIOR PARA QUE SE RESUELVA EL CONFLICTO; SE REFIERE A:', 'CONFLICTO NEGATIVO DE COMPETENCIA.', 'ART. 83', '181977'),
    (1402, 'SUB-1402', 'SBM3', 'SE REALIZARÁ EN VÍA INCIDENTAL, SIN SUSPENDER LOS PLAZOS PARA RESOLVER O PARA QUE OPERE EL SILENCIO ADMINISTRATIVO; SE REFIERE AL:', 'TRÁMITE DE ABSTENCIÓN.', 'ART. 92', '181978'),
    (1403, 'SUB-1403', 'SBM3', 'ES PRESENTADO EN PAPEL SIMPLE ACOMPAÑADO DE UNA COPIA CONFORME Y LEGIBLE, SALVO QUE FUERE NECESARIO UN NÚMERO MAYOR PARA NOTIFICAR A TERCEROS:', 'EL ESCRITO', 'ART. 114', '181979'),
    (1404, 'SUB-1404', 'SBM3', 'RÉGIMEN DE LA NOTIFICACIÓN PERSONAL.- LA NOTIFICACIÓN PERSONAL SE HARÁ EN (............................) QUE CONSTA EN EL EXPEDIENTE, O EN EL ÚLTIMO QUE LA PERSONA A QUIÉN DEBA NOTIFICAR HAYA SEÑALADO ANTE EL ÓRGANO ADMINISTRATIVO EN OTRO PROCEDIMIENTO ANÁLOGO A LA PROPIA ENTIDAD DENTRO DEL ÚLTIMO AÑO: (SEÑALE LA PALABRA CORRECTA):', 'EL DOMICILIO', 'ART. 21', '181980'),
    (1405, 'SUB-1405', 'SBM3', 'LOS ADMINISTRADOS PLANTEAN LA NULIDAD DE LOS ACTOS ADMINISTRATIVOS QUE LES CONCIERNAN POR MEDIO DE:', 'LOS RECURSOS ADMINISTRATIVOS', 'ART. 11', '181981'),
    (1406, 'SUB-1406', 'SBM3', 'MODALIDADES DEL ACTO ADMINISTRATIVO.- CUANDO UNA LEY LO AUTORICE, LA AUTORIDAD, MEDIANTE DECISIÓN EXPRESA, PUEDE SOMETER EL ACTO ADMINISTRATIVO A (..............................), SIEMPRE QUE DICHOS ELEMENTOS INCORPORADOS AL ACTO, SEAN COMPATIBLES CON EL ORDENAMIENTO LEGAL O CUANDO SE TRATE DE ASEGURAR CON ELLOS EL CUMPLIMIENTO DEL FIN PÚBLICO QUE PERSIGUE EL ACTO. SEÑALE LO CORRECTO:', 'CONDICIÓN, TÉRMINO O MODO', 'ART. 2', '181982'),
    (1407, 'SUB-1407', 'SBM3', 'SON REQUISITOS DE VALIDES DE LOS ACTOS ADMINISTRATIVOS. (SEÑALE LA RESPUESTA INCORRECTA):', 'PROCEDIMIENTO IRREGULAR', 'ART. 3', '181983'),
    (1408, 'SUB-1408', 'SBM3', 'SER EMITIDO POR EL ÓRGANO FACULTADO EN RAZÓN DE LA MATERIA, TERRITORIO, GRADO, TIEMPO O CUANTIA, A TRAVES DE LA AUTORIDAD REGULARMENTE NOMINADA AL MOMENTO DEL DICTADO Y EN CASO DE ÓRGANOS COLEGIADOS, CUMPLIENDO LOS REQUISITOS DE SESIÓN, QUORUM Y DELIBERACIÓN INDISPENSABLES PARA SU EMISIÓN. SEÑALE A QUE REQUISITO DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS CORRESPONDE:', 'COMPETENCIA', 'ART. 3', '181984'),
    (1409, 'SUB-1409', 'SBM3', 'LOS ACTOS ADMINISTRATIVOS DEBERÁN EXPRESARSE POR ESCRITO, SALVO QUE POR LA NATURALEZA Y CIRCUNSTANCIAS DEL CASO, (............................ ) HAYA PREVISTO OTRA FORMA, SIEMPRE QUE PERMITA TENER CONSTANCIA DE SU EXISTENCIA. COMPLETA LA FRASE CORRECTA:', 'EL ORDENAMIENTO JURÍDICO', 'ART. 4', '181985'),
    (1410, 'SUB-1410', 'SBM3', 'CUANDO EL ACTO ADMINISTRATIVO ES PRODUCIDO POR MEDIO DE SISTEMAS AUTOMATIZADOS, DEBE GARANTIZARSE AL ADMINISTRADO:', 'CONOCER EL NOMBRE Y CARGO DE LA AUTORIDAD QUE LO EXPIDE.', 'ART. 4', '181986'),
    (1411, 'SUB-1411', 'SBM3', 'EN EL ACTO DE NOTIFICACIÓN DEBE ENTREGARSE COPIA DEL ACTO NOTIFICADO Y SEÑALAR LA FECHA Y HORA EN QUE ES EFECTUADA, RECABANDO EL NOMBRE Y FIRMA DE LA PERSONA CON QUIÉN SE ENTIENDA LA DILIGENCIA. SI ÉSTA SE NIEGA SE: Ley N° 27444 - Ley del Procedimiento Administrativo General', 'SE HARÁ CONSTAR ASÍ EN EL ACTA.', 'ART. 21', '181987'),
    (1412, 'SUB-1412', 'SBM3', 'CUANDO PODRÁN ADOPTARSE LAS MEDIDAS QUE SEAN NECESARIAS PARA ASEGURAR LA PROTECCIÓN DEL INTERÉS PÚBLICO O LOS DERECHOS DE TERCEROS Y LA EFICACIA DE LA RESOLUCIÓN IMPUGNADA?', 'CUANDO SE DISPONE LA SUSPENSIÓN DE LA EJECUCIÓN DEL ACTO ADMINISTRATIVO', 'ART. 216', '181988'),
    (1413, 'SUB-1413', 'SBM3', 'EL ENUNCIADO: LAS NOTIFICACIONES POR PUBLICACIONES, A PARTIR DEL DÍA DE LA ÚLTIMA PÚBLICACIÓN EN EL DIARIO OFICIAL; ESTÁ REFERIDA A:', 'VIGENCIA DE LAS NOTIFICACIONES', 'ART. 25', '181989'),
    (1414, 'SUB-1414', 'SBM3', 'ART.26º NOTIFICACIONES DEFECTUOSAS.- EN CASO QUE SE DEMUESTRE QUE LA NOTIFICACIÓN SE HA REALIZADO SIN LAS FORMALIDADES Y REQUISITOS LEGALES, LA AUTORIDAD ORDENARÁ SE REHAGA, SUBSANANDO LAS OMISIONES EN QUE SE HUBIESEN INCURRIDO, (COMPLETE CON LA FRASE VERDADERA):', 'SIN PERJUICIO PARA EL ADMINISTRADO', 'ART. 26', '181990'),
    (1415, 'SUB-1415', 'SBM3', 'ART 26. NOTIFICACIONES DEFECTUOSAS.- LA DESESTIMACIÓN DEL CUESTIONAMIENTO A LA VALIDEZ DE UNA NOTIFICACIÓN, CAUSA QUE DICHA NOTIFICACIÓN: (SEÑALE LO CORRECTO)', 'OPERE DESDE LA FECHA EN QUE FUE REALIZADA', 'ART. 26', '181991'),
    (1416, 'SUB-1416', 'SBM3', 'SON VICIOS DEL ACTO ADMINISTRATIVO QUE CAUSEN NULIDAD DE PLENO DERECHO. (SEÑALE LA RESPUESTA CORRECTA):', 'EL DEFECTO O LA OMISIÓN DE ALGUNO DE SUS REQUISITOS DE VALIDEZ.', 'ART. 10', '181992'),
    (1417, 'SUB-1417', 'SBM3', 'MARQUE EL ENUNCIADO CORRECTO QUE PRECISA EL VICIO DEL ACTO ADMINISTRATIVO QUE CAUSA LA NULIDAD DE ÉSTE, DE PLENO DERECHO.', 'LOS ACTOS ADMINISTRATIVOS QUE SEAN CONSTITUTIVOS DE INFRACCIÓN PENAL.', 'ART. 10', '181993'),
    (1418, 'SUB-1418', 'SBM3', 'ART. 216º SUSPENSIÓN DE LA EJECUCIÓN.- LA INTERPOSICIÓN DE CUALQUIER RECURSO, EXCEPTO LOS CASOS EN QUE UNA NORMA LEGAL ESTABLEZCA LO CONTRARIO...:', 'NO SUSPENDERÁ LA EJECUCIÓN DEL ACTO IMPUGNADO', 'ART. 216', '181994'),
    (1419, 'SUB-1419', 'SBM3', 'ES UN ALCANCE DE LA NULIDAD DE LOS ACTOS ADMINISTRATIVOS:', 'LA NULIDAD DE UN ACTO SÓLO IMPLICA LA DE LOS SUCESIVOS EN EL PROCEDIMIENTO, CUANDO ESTÉN VINCULADOS A ÉL.', 'ART. 13', '181995'),
    (1420, 'SUB-1420', 'SBM3', 'ART. 14º CONSERVACIÓN DEL ACTO.- SON ACTOS ADMINISTRATIVOS AFECTADOS POR VICIOS NO TRASCENDENTES: (INDICAR EL INCORRECTO).', 'EL ACTO EMITIDO SIN INFRACCIONES A LAS FORMALIDADES NO ESENCIALES.', 'ART. 14', '181996'),
    (1421, 'SUB-1421', 'SBM3', 'ART 14.- CONSERVACION DEL ACTO.- CUANDO EL VICIO DEL ACTO ADMINISTRATIVO POR EL INCUMPLIMIENTO A SUS ELEMENTOS DE VALIDEZ, NO SEA (. ......................... ), PREVALECE LA CONSERVACIÓN DEL ACTO, PROCEDIENDOSE A SU ENMIENDA POR LA PROPIA AUTORIDAD EMISORA. (SEÑALE LO CORRECTO)', 'TRASCENDENTE', 'ART. 14', '181997'),
    (1422, 'SUB-1422', 'SBM3', 'LOS VICIOS INCURRIDOS EN LA EJECUCIÓN DE UN ACTO ADMINISTRATIVO, O EN SU NOTIFICACIÓN A LOS ADMINISTRADOS SON INDEPENDIENTES...:', 'DE SU VALIDEZ.', 'ART. 15', '181998'),
    (1423, 'SUB-1423', 'SBM3', 'LA EFICACIA ANTICIPADA DEL ACTO ADMINISTRATIVO SE DARÁ CUANDO:', 'FUERA MÁS FAVORABLE A LOS ADMINISTRADOS Y SIEMPRE QUE NO SE LESIONE DERECHOS FUNDAMENTALES.', 'ART. 17', '181999'),
    (1424, 'SUB-1424', 'SBM3', 'PRECISE UD, EN CUÁNTAS OPORTUNIDADES SE PUEDEN EJECUTAR LOS RECURSOS ADMINISTRATIVOS:.', 'POR UNA SOLA VEZ EN CADA PROCEDIMIENTO ADMINISTRATIVO.', 'ART. 214', '182000'),
    (1425, 'SUB-1425', 'SBM3', 'LA FINALIDAD DE LA LEY. NÚMERO 27444, ES:', 'ESTABLECER EL RÉGIMEN JÚRIDICO APLICABLE PARA QUE LA ACTUACIÓN DE LA ADMINISTRACIÓN PÚBLICA SIRVA A LA PROTECCIÓN DEL INTERÉS GENERAL.', 'TITULO PRELIMINAR ART. III', '182001'),
    (1426, 'SUB-1426', 'SBM3', 'SE ENTIENDE POR ENTIDADES DE ADMINISTRACIÓN PÚBLICA A LAS PERSONAS JURÍDICAS BAJO EL RÉGIMEN PRIVADO QUE PRESTAN SERVICIOS PÚBLICOS O EJERCEN FUNCIONES ADMINISTRATIVAS, EN VIRTUD DE, (..................................) CONFORME A LA NORMATIVA DE LA MATERIA.', 'CONCESIÓN, DELEGACIÓN O AUTORIZACIÓN DEL ESTADO', 'TITULO PRELIMINAR ART. I', '182002'),
    (1427, 'SUB-1427', 'SBM3', 'DEFINICIÓN DE PROCEDIMIENTO ADMINISTRATIVO (SEÑALE LA CORRECTA)', 'ES EL CONJUNTO DE ACTOS Y DILIGENCIAS TRAMITADOS EN LAS ENTIDADES', 'ART. 29 Ley N° 27444 - Ley del Procedimiento Administrativo General', '182003'),
    (1428, 'SUB-1428', 'SBM3', 'LA AUTORIDAD A QUIÉN COMPETA RESOLVER EL RECURSO PODRÁ SUSPENDER DE OFICIO O A PETICIÓN DE PARTE LA EJECUCIÓN DEL ACTO RECURRIDO CUANDO:', 'LA EJECUCIÓN PUDIERA CAUSAR PERJUICIOS DE IMPOSIBLE O DIFÍCIL REPARACIÓN', 'ART. 216', '182004'),
    (1429, 'SUB-1429', 'SBM3', 'ART 43.- VALOR DE DOCUMENTOS PÚBLICOS Y PRIVADOS.- LA COPIA DEL DOCUMENTO PRIVADO CUYA AUTENTICIDAD HA SIDO CERTIFICADA POR EL (. .............), TIENE VALIDEZ Y EFICACIA PLENA, EXCLUSIVAMENTE EN EL ÁMBITO DE ACTIVIDAD DE LA ENTIDAD QUE LA AUTENTÍCA. (COMPLETE LO CORRECTO)', 'FEDATARIO', 'ART. 43', '182005'),
    (1430, 'SUB-1430', 'SBM3', 'LA COPIA DEL DOCUMENTO PRIVADO CUYA AUTENTICIDAD HA SIDO CERTIFICADA POR EL FEDATARIO TIENE VALIDEZ Y EFICACIA PLENA: (SEÑALA LA CORRECTA)', 'EN EL ÁMBITO DE LA ACTIVIDAD DE LA ENTIDAD QUE LA AUTENTICA.', 'ART. 43', '182006'),
    (1431, 'SUB-1431', 'SBM3', 'VALOR DE DOCUMENTOS PÚBLICOS Y PRIVADOS: (SEÑALE LA INCORRECTA)', 'NO ES NECESARIO QUE EXISTA CONSTANCIA DE QUE CUALQUIER DOCUMENTO PÚBLICO ES AUTÉNTICO', 'ART. 43', '182007'),
    (1432, 'SUB-1432', 'SBM3', 'ENTENDIÉNDOSE COMO SUJETO DEL PROCEDIMIENTO ADMINISTRATIVO A LOS ADMINISTRADOS, ÉSTOS PUEDEN SER: (SEÑALE EL CORRECTO).', 'PERSONA NATURAL O JURÍDICA', 'ART. 50', '182008'),
    (1433, 'SUB-1433', 'SBM3', 'ART 50.- SUJETOS DEL PROCEDIMIENTO.- LA AUTORIDAD ADMINISTRATIVA ES EL AGENTE DE LAS ENTIDADES QUE BAJO CUALQUIER RÉGIMEN JURÍDICO Y EJERCIENDO POTESTADES PÚBLICAS CONDUCEN: (COMPLETE LO CORRECTO)', 'EL INICIO, LA INSTRUCCIÓN, LA SUSTANCIACIÓN, LA RESOLUCIÓN, LA EJECUCIÓN, O QUE DE OTRO MODO PARTICIPAN EN LA GESTIÓN DE LOS PROCEDIMIENTOS ADMINISTRATIVOS.', 'ART. 50', '182009'),
    (1434, 'SUB-1434', 'SBM3', 'ART. 50º.- SUJETOS DEL PROCEDIMIENTO.- PARA LOS EFECTOS DEL CUMPLIMIENTO DE LAS DISPOSICONES DEL DERECHO ADMINISTRATIVO, SE ENTIENDE POR SUJETOS DEL PROCEDIMIENTO A: (SEÑALE LA CORRECTA).', 'ADMINISTRADOS Y AUTORIDAD ADMINISTRATIVA', 'ART. 50', '182010'),
    (1435, 'SUB-1435', 'SBM3', 'ART 50.- SUJETOS DEL PROCEDIMIENTO.- EN LOS SUJETOS DEL PROCEDIMIENTO SE ENCUENTRAN COMPRENDIDOS LOS ADMINISTRADOS, CUYA DEFINICIÓN CORRECTA ES:', 'LA PERSONA NATURAL O JURÍDICA QUE, CUALQUIERA SEA SU CALIFICACIÓN O SITUACIÓN PROCEDIMENTAL, PARTICIPA EN EL PROCEDIMIENTO ADMINISTRATIVO.', 'ART. 50', '182011'),
    (1436, 'SUB-1436', 'SBM3', 'ART 50.- SUJETOS DEL PROCEDIMIENTO.- LA AUTORIDAD ADMINISTRATIVA ES EL AGENTE DE LAS ENTIDADES QUE BAJO CUALQUIER RÉGIMEN JURÍDICO Y EJERCIENDO POTESTADES PÚBLICAS CONDUCEN (. ..........................), O QUE DE OTRO MODO PARTICIPAN EN LA GESTIÓN DE LOS PROCEDIMIENTOS ADMINISTRATIVOS: (SEÑALE LO INCORRECTO)', 'LA ACTUACIÓN', 'ART. 50', '182012'),
    (1437, 'SUB-1437', 'SBM3', 'SE CONSIDERAN ADMINISTRADOS: (SEÑALE LA CORRECTA)', 'QUIENES PROMUEVEN EL PROCEDIMIENTO ADMINISTRATIVO COMO TITULARES DE DERECHOS', 'ART. 51', '182013'),
    (1438, 'SUB-1438', 'SBM3', 'EL PRINCIPIO SEGÚN EL CUÁL EL ADMINISTRADO ESTÁ FACULTADO, EN SUS RELACIONES CON LAS ENTIDADES, PARA REALIZAR TODA ACTUACIÓN QUE NO LE SEA EXPRESAMENTE PROHIBIDA POR ALGÚN DISPOSITIVO JURÍDICO; GUARDA RELACIÓN CON EL SIGUIENTE PRINCIPIO CONSTITUCIONAL (ART. 2ª, INC. 24):', 'NADIE ESTÁ OBLIGADO A HACER LO QUE LA LEY NO MANDA NI DEJAR DE HACER LO QUE ELLA NO PROHIBE', 'ART. 54', '182014'),
    (1439, 'SUB-1439', 'SBM3', 'LIBERTAD DE ACTUACIÓN PROCESAL: (SEÑALE LA CORRECTA)', 'EL ADMINISTRADO ESTÁ FACULTADO, EN SUS RELACIONES CON LAS ENTIDADES, PARA REALIZAR TODA ACTUACIÓN QUE NO LE SEA EXPRESAMENTE PROHIBIDA POR ALGÚN DISPOSITIVO JURÍDICO', 'ART. 54', '182015'),
    (1440, 'SUB-1440', 'SBM3', 'ART. 56º.- DEBERES GENERALES DE LOS ADMINISTRADOS EN EL PROCEDIMIENTO.- LOS ADMINISTRADOS TIENEN LOS SIGUIENTES DEBERES GENERALES: (SEÑALE EL INCORRECTO).', 'SOLICITAR ACTUACIONES MERAMENTE DILATORIAS', 'ART. 56', '182016'),
    (1441, 'SUB-1441', 'SBM3', 'DERECHO DE PETICIÓN ADMINISTRATIVA: CUALQUIER ADMINISTRADO PUEDE PROMOVER POR ESCRITO EL INICIO DE UN PROCEDIMIENTO ADMINISTRATIVO ANTE TODAS Y CUALQUIERA DE LAS ENTIDADES, EJERCIENDO EL DERECHO DE PETICIÓN RECONOCIDO EN EL ART.2° INCISO 20 DE LA CONSTITUCIÓN POLÍTICA DEL ESTADO.(SEÑALE LA RESPUESTA CORRECTA)', 'PUEDE HACERLO EN FORMA INDIVIDUAL O COLECTIVAMENTE', 'ART. 106', '182017'),
    (1442, 'SUB-1442', 'SBM3', 'INDIQUE USTED EL ENUNCIADO CORRECTO:', 'LOS DÍAS INHÁBILES SE FIJAN DENTRO DEL ÁMBITO GEOGRÁFICO NACIONAL O ALGUNO PARTICULAR', 'ART. 137', '182018'),
    (1443, 'SUB-1443', 'SBM3', 'LOS ADMINISTRADOS PUEDEN COMPARECER ASISTIDOS POR (..............................................) CUANDO SEA NECESARIO PARA LA MEJOR EXPOSICIÓN DE LA VERDAD DE LOS HECHOS: COMPLETE LA FRASE', 'ASESORES', 'ART. 58', '182019'),
    (1444, 'SUB-1444', 'SBM3', 'LA NOTIFICACIÓN CONSTITUYE UNA CONDICIÓN NECESARIA, PARA QUE EL ACTO ALCANCE SU EJECUTIVIDAD, PERO NO ES IMPRESCINDIBLE. LA LEGISLACIÓN HA PREVISTO REGLAS DE DISPENSA CONTEMPLADAS A CONTINUACIÓN, UNA DE LAS CUALES ES INCORRECTA:', 'NO ES NECESARIO CONTAR CON LA DOCUMENTACIÓN QUE EVIDENCIE DE MODO OBJETIVO LA TOMA DE CONOCIMIENTO DEL ADMINISTRADO', 'ART. 19', '182020'),
    (1445, 'SUB-1445', 'SBM3', 'DE LA REVISIÓN DEL ARTÍCULO 17* DE LA LEY DE PROCEDIMIENTO ADMINISTRATIVO GENERAL, SE APRECIA QUE, PARA LA RETROACTIVIDAD DE UN ACTO ADMINISTRATIVO, ES NECESARIO UNO DE LOS SIGUIENTES REQUISITOS:(SEÑALE LA RESPUESTA CORRECTA)', 'QUE EL SUPUESTO DE HECHO JUSTIFICATIVO DE LA DACIÓN DEL ACTO EXISTA A LA FECHA EN LA QUE PRETENDA RETROTRAERSE LA EFICACIA DEL ACTO', 'ART. 17', '182021'),
    (1446, 'SUB-1446', 'SBM3', 'DE LA REVISION DEL ARTÍCULO 17* DE LA LEY 27444 SE OBSERVA QUE EXISTEN ACTOS QUE LA NORMA CONSIDERA SUSCEPTIBLES DE ALCANZAR EFECTOS ANTICIPADOS; RESPECTO DE ESTOS, DE LOS ENUNCIADOS QUE SE DETALLAN A CONTINUACIÓN, SEÑALE USTED LA PREMISA INCORRECTA.', 'ES SUFICIENTE QUE LA ADMINISTRACIÓN ANULE EL ACTO VICIADO A FAVOR DEL ADMINISTRADO PARA APLICAR LA EFICACIA ANTICIPADA', 'ART. 17', '182022'),
    (1447, 'SUB-1447', 'SBM3', 'EL ACTO ADMINISTRATIVO ES EFICAZ: (SEÑALE LA RESPUESTA CORRECTA).', 'A PARTIR DE QUE LA NOTIFICACIÓN LEGALMENTE REALIZADA PRODUCE SUS EFECTOS.', 'ART. 16', '182023'),
    (1448, 'SUB-1448', 'SBM3', 'SON ACTOS ADMINISTRATIVOS AFECTADOS POR VICIOS NO TRASCENDENTALES LOS SIGUIENTES: (SEÑALE LA RESPUESTA CORRECTA) Ley N° 27444 - Ley del Procedimiento Administrativo General', 'CUANDO SE CONCLUYA INDUDABLEMENTE DE CUALQUIER OTRO MODO QUE EL ACTO ADMINISTRATIVO HUBIESE TENIDO EL MISMO CONTENIDO, DE NO HABERSE PRODUCIDO EL VICIO.', 'ART. 14', '182024'),
    (1449, 'SUB-1449', 'SBM3', 'SON ACTOS ADMINISTRATIVOS AFECTADOS POR VICIOS NO TRASCENDENTES LOS SIGUIENTES, (SEÑALE EL INCORRECTO):', 'AQUELLAS EMITIDAS SIN OMISIÓN DE DOCUMENTO NO ESENCIAL.', 'ART. 14', '182025'),
    (1450, 'SUB-1450', 'SBM3', 'DENTRO DE LOS ALCANCES DE LA NULIDAD CONTEMPLADOS EN LA LEY 27444, SEÑALE USTED EL CONCEPTO QUE NO CORRESPONDE:', 'LA NULIDAD DE UN ACTO IMPLICA NECESARIAMENTE LA DE LOS SUCESIVOS AÚN CUANDO NO ESTEN VINCULADOS A EL', 'ART. 13', '182026'),
    (1451, 'SUB-1451', 'SBM3', 'MARQUE EL ENUNCIADO CORRECTO QUE PRECISA EL VICIO DEL ACTO ADMINISTRATIVO QUE CAUSA LA NULIDAD DE ESTE, DE PLENO DERECHO:', 'LOS ACTOS ADMINISTRATIVOS QUE SEAN CONSTITUTIVOS DE INFRACCIÓN PENAL.', 'ART. 10', '182027'),
    (1452, 'SUB-1452', 'SBM3', 'SON VICIOS DEL ACTO ADMINISTRATIVO QUE CAUSEN SU NULIDAD DE PLENO DERECHO (SEÑALE EL INCORRECTO):', 'LOS ACTOS QUE SON BASADOS DENTRO DE LA CONSTITUCIÓN.', 'ART. 10', '182028'),
    (1453, 'SUB-1453', 'SBM3', 'SON REQUISITOS DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS. SEÑALE LO CORRECTO:', 'MOTIVACIÓN', 'ART. 3', '182029'),
    (1454, 'SUB-1454', 'SBM3', 'CUANDO DEBAN EMITIRSE VARIOS ACTOS ADMINISTRATIVOS DE LA MISMA NATURALEZA PODRÁ SER EMPLEADA FIRMA ( .........................) O INTEGRARSE EN UN SÓLO DOCUMENTO BAJO UNA MISMA MOTIVACIÓN, SIEMPRE QUE SE INDIVIDUALICE A LOS ADMINISTRADOS SOBRE LOS QUE RECAE LOS EFECTOS DEL ACTO. SEÑALE LO CORRECTO:', 'MECÁNICA', 'ART. 4', '182030'),
    (1455, 'SUB-1455', 'SBM3', 'LOS ACTOS ADMINISTRATIVOS DEBEN EXPRESAR SU RESPECTIVO OBJETO, DE TAL MODO QUE PUEDA DETERMINARSE INEQUÍVOCAMENTE SUS EFECTOS JURÍDICOS. SU CONTENIDO SE AJUSTARÁ A LO DISPUESTO EN EL ORDENAMIENTO JURÍDICO, DEBIENDO SER LÍCITO, PRECISO, POSIBLE FÍSICA Y JURÍDICAMENTE, Y COMPRENDER LAS CUESTIONES SURGIDAS DE LA MOTIVACIÓN, ES UN REQUISITO DE VALIDEZ DE LOS ACTOS ADMINISTRATIVOS CONOCIDO COMO:', 'OBJETO O CONTENIDO', 'ART. 3', '182031'),
    (1456, 'SUB-1456', 'SBM3', 'LAS AUTORIDADES ADMINISTRATIVAS NO PODRÁN DEJAR DE RESOLVER LAS CUESTIONES QUE SE LE PROPONGAN, POR DEFICIENCIAS DE SUS FUENTES; EN TALES CASOS ACUDIRÁN A:', 'PRINCIPIOS DE PROCEDIMIENTOS ADMINISTRATIVO PREVISTOS EN LA LEY NÚMERO 27444', 'TITULO PRELIMINAR ART. VIII', '182032'),
    (1457, 'SUB-1457', 'SBM3', 'PRECISE CUÁL ES EL EFECTO QUE SE ORIGINA CUANDO EL RECURRENTE CALIFICA ERRÓNEAMENTE EL RECURSO:', 'NO SERÁ OBSTÁCULO PARA SU TRAMITACIÓN.', 'ART. 213', '182033'),
    (1458, 'SUB-1458', 'SBM3', 'EN CASO DE DUDA SOBRE LA AUTENTICIDAD DE LA FIRMA DEL ADMINISTRADO, LA AUTORIDAD PUEDE NOTIFICARLO PARA QUE RATIFIQUE LA FIRMA SIN PERJUICIO DE LA CONTINUACIÓN DEL PROCEDIMIENTO EN UN PLAZO DE:', 'DENTRO DE UN PLAZO PRUDENCIAL', 'ART. 129', '182034'),
    (1459, 'SUB-1459', 'SBM3', 'PLAZOS MÁXIMOS PARA REALIZAR ACTOS PROCEDIMENTALES.- EN EL PLAZO MÁXIMO PARA LA EMISIÓN DE DICTÁMENES PERITAJES, INFORMES Y SIMILARES SERÁ DENTRO DE (. .....................) DÍAS DESPUÉS DE SOLICITADOS, PUDIENDO SER PRORROGADO A TRES DÍAS MÁS SI LA DILIGENCIA REQUIERE EL TRASLADO FUERA DE SU SEDE O LA ASISTENCIA DE TERCEROS: (SEÑALE LA RESPUESTA CORRECTA).', 'SIETE DÍAS.', 'ART. 132', '182035'),
    (1460, 'SUB-1460', 'SBM3', 'PLAZOS MÁXIMOS PARA REALIZAR ACTOS PROCEDIMENTALES.- PARA LA RECEPCIÓN Y DERIVACIÓN DE UN ESCRITO A LA UNIDAD COMPETENTE, A FALTA DE UN PLAZO ESTABLECIDO POR LEY EXPRESA, LA ACTUACIÓN DEBE PRODUCIRSE DENTRO DE: (SEÑALE LA RESPUESTA CORRECTA).', 'MISMO DÍA DE SU PRESENTACIÓN', 'ART. 132', '182036'),
    (1461, 'SUB-1461', 'SBM3', 'ART. 132.- PLAZOS MÁXIMOS PARA REALIZAR ACTOS PROCEDIMENTALES.- A FALTA DE PLAZO ESTABLECIDO POR LEY EXPRESA, LAS ACTUACIONES DEBEN PRODUCIRSE DENTRO DE LOS SIGUIENTES: (SEÑALAR EL INCORRECTO)', 'PARA EMISIÓN DE PERITAJES: DENTRO DEL SEGUNDO DÍA DE SOLICITADOS.', 'ART. 132', '182037'),
    (1462, 'SUB-1462', 'SBM3', 'PLAZOS MÁXIMOS PARA REALIZAR ACTOS PROCEDIMENTALES.- PARA ACTOS DE CARGO DEL ADMINISTRADO, REQUERIDOS POR LA AUTORIDAD, COMO ENTREGA DE INFORMACIÓN, RESPUESTA A LAS CUESTIONES SOBRE LAS CUALES DEBAN PRONUNCIARSE LAS ACTUACIONES DEBEN PRODUCIRSE DENTRO DE: (SEÑALE LA CORRECTA).', 'DIEZ DÍAS DE SOLICITADOS', 'ART. 132', '182038'),
    (1463, 'SUB-1463', 'SBM3', 'PRECISE USTED EN CUANTO AL INICIO DEL CÓMPUTO DEL PLAZO; CÓMO ES CONTADO EL PLAZO EXPRESADO EN DÍAS:', 'A PARTIR DEL DÍA HÁBIL SIGUIENTE DE AQUEL EN QUE SE PRACTIQUE LA NOTIFICACIÓN O PÚBLICACIÓN DEL ACTO.', 'ART. 133', '182039'),
    (1464, 'SUB-1464', 'SBM3', 'EN EL TRANSCURSO DEL PLAZO, CUANDO ESTE ES SEÑALADO POR DÍAS, SE ENTENDERÁ:', 'POR HÁBILES CONSECUTIVOS, EXCLUYENDO DEL CÓMPUTO AQUELLOS NO LABORABLES DEL SERVICIO, Y LOS FERIADOS NO LABORABLES DE ORDEN NACIONAL O REGIONAL.', 'ART. 134', '182040'),
    (1465, 'SUB-1465', 'SBM3', 'PRECISE USTED EN QUÉ CIRCUNSTANCIA EL TRANSCURSO DEL PLAZO ES ENTENDIDO PRORROGADO AL PRIMER DÍA HÁBIL SIGUIENTE:', 'CUANDO POR CUALQUIER CIRCUNSTANCIA LA ATENCIÓN AL PÚBLICO ESE DÍA NO FUNCIONE DURANTE HORARIO NORMAL.', 'ART. 134', '182041'),
    (1466, 'SUB-1466', 'SBM3', 'PRECISE UD, EN QUÉ CIRCUNSTANCIAS CUANDO EL PLAZO ES FIJADO EN MESES O AÑOS, ES ENTENDIDO QUE ÉSTE, EXPIRA EL PRIMER DÍA HÁBIL DEL SIGUIENTE MES CALENDARIO:', 'SI EN EL MES DE SU VENCIMIENTO NO HUBIERE DÍA IGUAL A AQUEL EN QUE COMENZÓ EL CÓMPUTO.', 'ART. 134', '182043'),
    (1467, 'SUB-1467', 'SBM3', 'PRECISE USTED LAS ACCIONES A SEGUIR A FIN DE LOGRAR QUE LA NORMA QUE FIJA LOS DÍAS INHÁBILES SEA DE CONOCIMIENTO DE LOS ADMINISTRADOS:', 'DEBE PÚBLICARSE PREVIAMENTE Y DIFUNDIRSE PERMANENTEMENTE EN LOS AMBIENTES DE LAS ENTIDADES.', 'ART. 137', '182044'),
    (1468, 'SUB-1468', 'SBM3', 'PRECISE QUÉ AUTORIDAD FIJA LOS DÍAS INHÁBILES, A EFECTO DEL CÓMPUTO DE PLAZOS ADMINISTRATIVOS:', 'EL PODER EJECUTIVO', 'ART. 137', '182045'),
    (1469, 'SUB-1469', 'SBM3', 'MENCIONE USTED EL ENUNCIADO CORRECTO EN RELACIÓN AL CONTENIDO DE LA NOTIFICACIÓN:', 'LA FECHA DE VIGENCIA DEL ACTO NOTIFICADO Y CON LA MENCIÓN DE SI AGOTARE LA VÍA ADMINISTRATIVA', 'ART. 24', '182048'),
    (1470, 'SUB-1470', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ CONTENER: (SEÑALE LA CORRECTA).', 'EL TEXTO ÍNTEGRO DEL ACTO ADMINISTRATIVO, INCLUYENDO SU MOTIVACIÓN', 'ART. 24', '182049'),
    (1471, 'SUB-1471', 'SBM3', 'EN LA NOTIFICACIÓN A PLURALIDAD DE INTERESADOS; CUANDO SEAN VARIOS SUS DESTINATARIOS, EL ACTO SERÁ NOTIFICADO:', 'PERSONALMENTE A TODOS', 'ART. 22', '182050'),
    (1472, 'SUB-1472', 'SBM3', 'DE LAS PREMISAS DESCRITAS A CONTINUACIÓN, RELACIONADAS CON LA NOTIFICACIÓN A PLURALIDAD DE INTERESADOS, SEÑALE USTED LA QUE ES INCORRECTA.', '10 ADMINISTRADOS CON LOS DESTINATARIOS MÚLTIPLES, MENORES DE INTERESES COMUNES SIN REPRESENTACIÓN SERÁN NOTIFICADOS POR INTERMEDIO DE LA PERSONA QUE ENCABECE EL ESCRITO INICIAL', 'ART. 22', '182051'),
    (1473, 'SUB-1473', 'SBM3', 'LOS ADMINISTRADOS RESPECTO DEL PROCEDIMIENTO ADMINISTRATIVO, ASÍ COMO QUIENES PARTICIPEN EN ÉL TIENEN LOS SIGUIENTES DEBERES GENERALES: (SEÑALE EL CORRECTO).', 'ABSTENERSE DE FORMULAR PRETENSIONES O ARTICULACIONES ILEGALES', 'ART. 56', '182052'),
    (1474, 'SUB-1474', 'SBM3', 'COMPARECENCIA PERSONAL.- SEÑALE LA INCORRECTA:', 'LAS ENTIDADES PUEDEN CONVOCAR LA COMPARECENCIA PERSONAL AÚN CUANDO LA LEY NO LES FACULTE', 'ART. 58', '182053'),
    (1475, 'SUB-1475', 'SBM3', 'EL DÍA Y HORA EN QUE DEBE COMPARECER EL CITADO; NO PUEDE SER:', 'ANTES DEL TERCER DÍA DE RECIBIDA LA CITACIÓN', 'ART. 59', '182054'),
    (1476, 'SUB-1476', 'SBM3', 'EL CITATORIO SE RIGE POR EL RÉGIMEN COMÚN DE LA NOTIFICACIÓN HACIENDO CONSTAR EN ELLA LO SIGUIENTE:(SEÑALA LA RESPUESTA CORRECTA)', 'LA DISPOSICIÓN LEGAL QUE FACULTA AL ÓRGANO A REALIZAR ESTA CITACIÓN', 'ART. 59', '182055'),
    (1477, 'SUB-1477', 'SBM3', 'RECIBIDA LA SOLICITUD O LA DISPOSICIÓN DE AUTORIDAD SUPERIOR SEGÚN EL CASO, PARA INICIAR EL PROCEDIMIENTO, LAS AUTORIDADES DE OFICIO DEBEN ASEGURARSE DE SU PROPIA COMPETENCIA PARA PROSEGUIR CON EL NORMAL DESARROLLO DEL PROCEDIMIENTO SIGUIENDO LOS CRITERIOS APLICABLES AL CASO DE: (SEÑALE LO INCORRECTO).', 'LA PENALIDAD', 'ART. 80', '182056'),
    (1478, 'SUB-1478', 'SBM3', 'RECIBIDA LA SOLICITUD O LA DISPOSICIÓN DE AUTORIDAD SUPERIOR, SEGÚN EL CASO PARA INICIAR UN PROCEDIMIENTO, LAS AUTORIDADES DE OFICIO DEBEN ASEGURARSE DE SU PROPIA COMPETENCIA PARA PROSEGUIR CON EL NORMAL DESARROLLO DEL PROCEDIMIENTO, SIGUIENDO LOS CRITERIOS APLICABLES AL CASO DE LA MATERIA: (SEÑALE LA CORRECTA)', 'EL TERRITORIO, EL TIEMPO, EL GRADO O LA CUANTÍA', 'ART. 80', '182057'),
    (1479, 'SUB-1479', 'SBM3', 'EN CASO DE SUSCITARSE CONFLICTO NEGATIVO DE COMPETENCIA, EL EXPEDIENTE ES ELEVADO AL (. .....................), PARA QUE RESUELVA EL CONFLICTO. (SEÑALE LO CORRECTO)', 'ÓRGANO INMEDIATO SUPERIOR Ley N° 27444 - Ley del Procedimiento Administrativo General', 'ART. 83', '182058'),
    (1480, 'SUB-1480', 'SBM3', 'EN CUANTO AL DERECHO DE PETICIÓN ADMINISTRATIVA:(SEÑALE LA RESPUESTA CORRECTA).', 'CUALQUIER ADMINISTRADO INDIVIDUAL O COLECTIVAMENTE, PUEDE PROMOVER POR ESCRITO EL INICIO DE UN PROCEDIMIENTO ADMINISTRATIVO ANTE TODAS Y CUALESQUIERA DE LAS ENTIDADES EJERCIENDO EL DERECHO DE PETICIÓN.', 'ART. 106', '182059'),
    (1481, 'SUB-1481', 'SBM3', 'INDIQUE CUÁL ENUNCIADO CORRESPONDE AL DERECHO DE PETICIÓN ADMINISTRATIVA.', 'ESTE DERECHO IMPLICA LA OBLIGACIÓN DE DAR AL INTERESADO UNA RESPUESTA POR ESCRITO DENTRO DEL PLAZO LEGAL.', 'ART. 106', '182060'),
    (1482, 'SUB-1482', 'SBM3', 'CUAL DE LOS ENUNCIADOS CORRESPONDE A LA FACULTAD CONTRADICCIÓN ADMINISTRATIVA:', 'LA RECEPCIÓN O ATENCIÓN DE UNA CONTRADICCIÓN NO PUEDE SER CONDICIONADA AL PREVIO CUMPLIMIENTO DEL ACTO RESPECTIVO', 'ART. 109', '182061'),
    (1483, 'SUB-1483', 'SBM3', 'ES UNO DE LOS PRINCIPIOS DEL PROCEDIMIENTO ADMINISTRATIVO:', 'RAZONABILIDAD', 'TITULO PRELIMINAR ART. IV', '182062'),
    (1484, 'SUB-1484', 'SBM3', 'ES UNO DE LOS PRINCIPIOS DE LA POTESTAD SANCIONADORA ADMINISTRATIVA:', 'DEBIDO PROCEDIMIENTO.', 'TITULO PRELIMINAR ART. IV Ley N° 27444 - Ley del Procedimiento Administrativo General', '182063'),
    (1485, 'SUB-1485', 'SBM3', 'EN QUÉ DEBERÁ SUSTENTARSE EL RECURSO DE RECONSIDERACIÓN :', 'EN NUEVA PRUEBA.', 'ART. 208', '182064'),
    (1486, 'SUB-1486', 'SBM3', 'EL ERROR EN LA CALIFICACIÓN DEL RECURSO POR PARTE DEL RECURRENTE NO SERÁ OBSTÁCULO PARA SU TRAMITACIÓN SIEMPRE QUE DEL ESCRITO SE DEDUZCA SU :', 'VERDADERO CARÁCTER.', 'ART. 213', '182065'),
    (1487, 'SUB-1487', 'SBM3', 'UNA VEZ VENCIDOS LOS PLAZOS PARA INTERPONER LOS RECURSOS ADMINISTRATIVOS SE PERDERÁ EL DERECHO A :', 'ARTICULARLOS QUEDANDO FIRME EL ACTO', 'ART. 212', '182066'),
    (1488, 'SUB-1488', 'SBM3', 'LOS RECURSOS ADMINISTRATIVOS SE EJERCITARÁN POR :', 'UNA SOLA VEZ EN CADA PROCEDIMIENTO ADMINISTRATIVO Y NUNCA SIMULTÁNEAMENTE.', 'ART. 214', '182067'),
    (1489, 'SUB-1489', 'SBM3', 'MEDIDAS CAUTELARES; NO SE PODRÁN DICTAR MEDIDAS QUE PUEDAN CAUSAR PERJUICIO DE IMPOSIBLE :', 'REPARACIÓN A LOS ADMINISTRADOS.', 'ART. 146', '182068'),
    (1490, 'SUB-1490', 'SBM3', 'EFECTOS DEL VENCIMIENTO DEL PLAZO; EL PLAZO VENCE EL ÚLTIMO MOMENTO DEL DÍA HÁBIL FIJADO; SI ANTES DE ESA FECHA SON CUMPLIDAS LAS ACTUACIONES PARA LAS QUE FUERA ESTABLECIDO. PUEDE VENCERSE :', 'ANTICIPADAMENTE.', 'ART. 140 Ley N° 27444 - Ley del Procedimiento Administrativo General', '182069'),
    (1491, 'SUB-1491', 'SBM3', 'EL INCUMPLIMIENTO INJUSTIFICADO DE LOS PLAZOS PREVISTOS PARA LAS ACTUACIONES DE LAS ENTIDADES GENERA RESPONSABILIDAD DISCIPLINARIA PARA LA AUTORIDAD OBLIGADA, SIN PERJUICIO DE LA :', 'RESPONSABILIDAD CIVIL POR LOS DAÑOS Y PERJUICIOS QUE PUDIERA HABER OCASIONADO.', 'ART. 143', '182070'),
    (1492, 'SUB-1492', 'SBM3', 'SEÑALE LA ALTERNATIVA QUE CORRESPONDA; LA RESOLUCIÓN DEL RECURSO ESTIMARÁ EN TODO O EN PARTE O DESESTIMARÁ LAS PRETENSIONES FORMULADAS EN EL MISMO O DECLARARÁ SU :', 'INADMISIÓN.', 'ART. 217', '182071'),
    (1493, 'SUB-1493', 'SBM3', 'SE INTERPONDRÁ CUANDO LA IMPUGNACIÓN SE SUSTENTE EN DIFERENTE INTERPRETACIÓN DE LAS PRUEBAS PRODUCIDAS O CUANDO SE TRATE DE CUESTIONES DE PURO DERECHO, DEBIENDO DIRIGIRSE A LA MISMA AUTORIDAD QUE EXPIDIÓ EL ACTO QUE SE IMPUGNA PARA QUE ELEVE LO ACTUADO AL SUPERIOR JERÁRQUICO; CORRESPONDE A :', 'RECURSO DE APELACIÓN.', 'ART. 209', '182072'),
    (1494, 'SUB-1494', 'SBM3', 'SOLO EN CASO QUE POR LEY O DECRETO LEGISLATIVO SE ESTABLEZCA EXPRESAMENTE, CABE LA INTERPOSICIÓN DEL RECURSO ADMINISTRATIVO DE:', 'REVISIÓN', 'ART. 207', '182073'),
    (1495, 'SUB-1495', 'SBM3', 'LAS NOTIFICACIONES SURTIRÁN EFECTOS CONFORME A LA SIGUIENTE REGLA; MARQUE LA RESPUESTA CORRECTA:', 'LAS CURSADAS MEDIANTE CORREO CERTIFICADO, OFICIO, CORREO ELECTRÓNICO Y ANÁLOGOS: EL DÍA QUE CONSTE HABER SIDO RECIBIDAS.', 'ART. 25', '182074'),
    (1496, 'SUB-1496', 'SBM3', 'LAS NOTIFICACIONES SURTIRÁN EFECTOS CONFORME A LA SIGUIENTE REGLA; MARQUE LA RESPUESTA CORRECTA:', 'LAS NOTIFICACIONES PERSONALES: EL DÍA QUE HUBIEREN SIDO REALIZADAS.', 'ART. 25', '182075'),
    (1497, 'SUB-1497', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ PRACTICARSE A MÁS TARDAR DENTRO DEL PLAZO DE 5 DÍAS, A PARTIR DE LA EXPEDICIÓN DEL ACTO QUE SE NOTIFIQUE, Y DEBERÁ CONTENER; MARQUE LA RESPUESTA CORRECTA:', 'LA EXPRESIÓN DE LOS RECURSOS QUE PROCEDEN, EL ÓRGANO ANTE EL CUÁL DEBEN PRESENTARSE LOS RECURSOS Y EL PLAZO PARA INTERPONERLOS.', 'ART. 24', '182076'),
    (1498, 'SUB-1498', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ PRACTICARSE A MÁS TARDAR DENTRO DEL PLAZO DE 5 DÍAS, A PARTIR DE LA EXPEDICIÓN DEL ACTO QUE SE NOTIFIQUE, Y DEBERÁ CONTENER:', 'LA IDENTIFICACIÓN DEL PROCEDIMIENTO DENTRO DEL CUÁL HAYA SIDO DICTADO.', 'ART. 24', '182077'),
    (1499, 'SUB-1499', 'SBM3', 'TODA NOTIFICACIÓN DEBERÁ PRACTICARSE A MÁS TARDAR DENTRO DEL PLAZO DE 5 DÍAS, A PARTIR DE LA EXPEDICIÓN DEL ACTO QUE SE NOTIFIQUE, Y DEBERÁ CONTENER; MARQUE LA RESPUESTA CORRECTA:', 'LA FECHA DE VIGENCIA DEL ACTO NOTIFICADO, Y CON LA MENCIÓN DE SI AGOTARE LA VÍA ADMINISTRATIVA.', 'ART. 24', '182078'),
    (1500, 'SUB-1500', 'SBM3', 'LA DECLARATORIA DE NULIDAD Y LOS ACTOS QUE SE DICTEN EN ENMIENDA, TAMBIÉN TIENEN EFICACIA :', 'ANTICIPADA.', 'ART. 17', '182079')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

